INSERT INTO mains (created_at, updated_at, name, subtitle, description, user_id, user_nickname) VALUES
-- Sociologia (3 usuários)
(NOW(), NOW(), 'Reflexões Sociais', 'Pensando a sociedade contemporânea', 'Bem-vindo ao meu espaço de análise social! Aqui exploramos desde as teorias clássicas de Durkheim até os desafios da sociedade digital. Vamos discutir desigualdades estruturais, movimentos sociais emergentes e as transformações culturais do nosso tempo, com artigos semanais que conectam teoria e prática.', (SELECT id FROM users WHERE nickname = 'jpbandeira'), 'jpbandeira'),
(NOW(), NOW(), 'Diálogos Sociológicos', 'Por uma compreensão crítica da realidade', 'Este é um espaço dedicado à análise sociológica das relações humanas, onde exploramos desde microinterações cotidianas até macroestruturas sociais. Com abordagens que vão da fenomenologia à teoria crítica, oferecemos ferramentas para desnaturalizar o mundo social e compreender seus mecanismos ocultos.', (SELECT id FROM users WHERE nickname = 'cadu'), 'cadu'),
(NOW(), NOW(), 'Sociedade em Foco', 'Análises e debates contemporâneos', 'Neste ambiente virtual, mergulhamos nos fenômenos sociais mais relevantes do século XXI. Desde a crise das democracias liberais até os impactos sociais da inteligência artificial, nossa abordagem interdisciplinar conecta sociologia, antropologia e ciência política para entender os complexos desafios de nossa era.', (SELECT id FROM users WHERE nickname = 'mary'), 'mary'),

-- Tecnologia (5 usuários)
(NOW(), NOW(), 'Segurança Digital', 'Protegendo seu espaço online', 'Como especialista em segurança cibernética, compartilho conhecimentos avançados sobre proteção de dados, ethical hacking e compliance digital. Aqui você encontrará desde tutoriais para iniciantes até análises técnicas profundas sobre as últimas vulnerabilidades e tendências em cybersecurity.', (SELECT id FROM users WHERE nickname = 'mjaborandy'), 'mjaborandy'),
(NOW(), NOW(), 'Código e Criptografia', 'Desenvolvimento seguro na era digital', 'Neste espaço exploramos a interseção entre programação e segurança da informação. Abordamos desde fundamentos de criptografia aplicada até arquiteturas de sistemas seguros, com estudos de caso reais e análises de frameworks de proteção de dados.', (SELECT id FROM users WHERE nickname = 'thi'), 'thi'),
(NOW(), NOW(), 'Tecnologia em Foco', 'Do hardware ao firewall', 'Como profissional de TI com 10 anos de experiência, ofereço análises técnicas detalhadas sobre infraestrutura de redes, arquitetura de sistemas e gestão de vulnerabilidades. Nosso conteúdo vai desde reviews de equipamentos até metodologias de pentesting avançado.', (SELECT id FROM users WHERE nickname = 'brunim'), 'brunim'),
(NOW(), NOW(), 'Bytes e Firewalls', 'Segurança desde o primeiro bit', 'Este é um espaço dedicado à cultura de segurança digital, onde discutimos desde princípios básicos de hardening até técnicas avançadas de forensic analysis. Nosso objetivo é formar profissionais capazes de pensar como hackers para construir sistemas verdadeiramente seguros.', (SELECT id FROM users WHERE nickname = 'dieguito'), 'dieguito'),
(NOW(), NOW(), 'Cyber Security', 'Proteção em primeiro lugar', 'Especializado em segurança ofensiva, compartilho conhecimentos sobre penetration testing, análise de malware e gestão de riscos cibernéticos. Aqui você encontra laboratórios práticos, walkthroughs de CTFs e análises aprofundadas de vulnerabilidades zero-day.', (SELECT id FROM users WHERE nickname = 'luquinhas'), 'luquinhas'),

-- Português (3 usuários)
(NOW(), NOW(), 'Língua Portuguesa', 'A beleza das palavras', 'Como mestre em linguística, convido você a explorar conosco as riquezas e peculiaridades do idioma português. Desde variações dialetais até análises sintáticas profundas, nosso conteúdo abrange tanto a norma culta quanto as vibrantes manifestações do português popular.', (SELECT id FROM users WHERE nickname = 'eug'), 'eug'),
(NOW(), NOW(), 'Literatura e Gramática', 'A arte da linguagem', 'Neste espaço conjugamos o rigor gramatical com a sensibilidade literária. Analisamos obras clássicas e contemporâneas, explorando como os recursos linguísticos constroem sentido, enquanto oferecemos dicas práticas para dominar a norma culta sem perder a expressividade.', (SELECT id FROM users WHERE nickname = 'nanda'), 'nanda'),
(NOW(), NOW(), 'Palavras em Foco', 'A arte de bem escrever', 'Como redatora profissional com 15 anos de experiência, compartilho técnicas avançadas de escrita criativa, estruturação textual e estilo. Nosso conteúdo vai desde fundamentos de coesão textual até análises estilísticas de grandes autores, sempre com exercícios práticos.', (SELECT id FROM users WHERE nickname = 'lau'), 'lau'),

-- Outros temas (9 usuários restantes)
(NOW(), NOW(), 'Arte Contemporânea', 'Expressões modernas', 'Como curadora independente, apresento análises críticas das principais tendências artísticas globais. Exploramos desde instalações imersivas até street art, discutindo como a arte contemporânea reflete e questiona as complexidades do mundo atual.', (SELECT id FROM users WHERE nickname = 'aninha'), 'aninha'),
(NOW(), NOW(), 'Viagens pelo Mundo', 'Descubra novos lugares', 'Com mais de 40 países visitados, compartilho guias detalhados, rotas alternativas e dicas culturais essenciais. Nosso foco são experiências autênticas que vão além do turismo convencional, com ênfase em intercâmbio cultural e viagens sustentáveis.', (SELECT id FROM users WHERE nickname = 'gabi'), 'gabi'),
(NOW(), NOW(), 'Culinária Criativa', 'Receitas e técnicas inovadoras', 'Como chef especializada em fusão gastronômica, ensino a combinar sabores tradicionais com técnicas modernas. Nossos conteúdos incluem desde fundamentos de cozinha profissional até experimentações ousadas, sempre com explicações científicas sobre os processos culinários.', (SELECT id FROM users WHERE nickname = 'ju'), 'ju'),
(NOW(), NOW(), 'Música Indie', 'Som alternativo', 'Produtor musical e caçador de novidades, apresento análises aprofundadas de álbuns, entrevistas exclusivas com artistas emergentes e crônicas sobre a cena musical independente global. Nosso foco é descobrir talentos antes que explodam no mainstream.', (SELECT id FROM users WHERE nickname = 'rafa'), 'rafa'),
(NOW(), NOW(), 'Fitness em Casa', 'Saúde prática', 'Como educador físico especializado em treinamento funcional, desenvolvo programas adaptáveis para todos os níveis. Nossos conteúdos incluem desde rotinas básicas até protocolos avançados, sempre com ênfase em biomecânica correta e periodização inteligente.', (SELECT id FROM users WHERE nickname = 'ali'), 'ali'),
(NOW(), NOW(), 'Fotografia Urbana', 'Capturando cidades', 'Fotógrafo profissional especializado em paisagens urbanas, ensino a ver a cidade com novos olhos. Compartilho técnicas avançadas de composição, edição não-destrutiva e narrativa visual, além de análises críticas de trabalhos referenciais na área.', (SELECT id FROM users WHERE nickname = 'camilinha'), 'camilinha'),
(NOW(), NOW(), 'Meditação Guiada', 'Encontre seu centro', 'Instrutor de mindfulness com formação em psicologia, ofereço programas estruturados para redução de estresse. Nossas práticas combinam técnicas ancestrais com abordagens científicas modernas, adaptadas para desafios contemporâneos como a hiperconexão digital.', (SELECT id FROM users WHERE nickname = 'lis'), 'lis'),
(NOW(), NOW(), 'Startups Inovadoras', 'Empreendedorismo digital', 'Consultor especializado em scale-ups, analiso cases reais de modelos de negócio disruptivos. Nosso conteúdo cobre desde validação de ideias até estratégias de growth hacking, com entrevistas exclusivas com fundadores de unicórnios brasileiros.', (SELECT id FROM users WHERE nickname = 'fabim'), 'fabim'),
(NOW(), NOW(), 'Jardinagem Urbana', 'Verde na cidade', 'Engenheira agrônoma especializada em paisagismo urbano, ensino a criar oásis verdes em pequenos espaços. Compartilho técnicas de cultivo orgânico, seleção de espécies resilientes e designs funcionais que transformam varandas em jardins produtivos.', (SELECT id FROM users WHERE nickname = 'igorzin'), 'igorzin');


























