INSERT INTO contents (name, description, item_id, created_at, updated_at) VALUES
-- Contents for 'Teoria Ator-Rede' (item_id 1)
('Introdução', 'A Teoria Ator-Rede (TAR), desenvolvida por Bruno Latour e Michel Callon, propõe uma abordagem simétrica para analisar as relações entre humanos e não-humanos na construção de redes sociais. Esta teoria desafia as dicotomias tradicionais entre sujeito/objeto e natureza/cultura, enfatizando como atores humanos e não-humanos se associam para formar redes estáveis. Na sociedade contemporânea, podemos observar essa teoria em ação ao analisar como plataformas digitais, algoritmos e dispositivos técnicos se tornam atores fundamentais nas dinâmicas sociais.', 1, NOW(), NOW()),
('Conceitos-chave', 'Os principais conceitos da TAR incluem: ator-rede (que considera tanto humanos quanto não-humanos como atores), tradução (processo pelo qual os atores se alinham em redes), inscrição (como as relações se estabilizam em artefatos), e caixa-preta (quando as redes se tornam tão estáveis que sua complexidade interna é esquecida). Esses conceitos nos ajudam a entender fenômenos como as redes sociais digitais, onde plataformas técnicas modificam profundamente o comportamento humano.', 1, NOW(), NOW()),
('Aplicações', 'Na prática, a TAR tem sido aplicada para estudar desde controvérsias científicas até o desenvolvimento de tecnologias. Por exemplo, podemos analisar como um aplicativo de mobilidade urbana reconfigura as relações entre passageiros, motoristas, reguladores e a infraestrutura da cidade. A teoria nos permite mapear essas associações complexas sem privilegiar explicações puramente sociais ou técnicas.', 1, NOW(), NOW()),
('Críticas', 'Apesar de inovadora, a TAR recebe críticas por seu relativismo radical e por dificultar a análise de estruturas de poder estáveis. Alguns sociólogos argumentam que a teoria negligencia o papel das desigualdades estruturais ao tratar todos os atores como simétricos. Outros questionam se objetos técnicos podem realmente ter "agência" no mesmo sentido que os humanos.', 1, NOW(), NOW()),

-- Contents for 'Pós-modernidade' (item_id 2)
('Definição', 'A pós-modernidade representa uma ruptura com os grandes relatos modernos como progresso, razão absoluta e verdades universais. Pensadores como Lyotard, Baudrillard e Foucault argumentam que vivemos em uma era de fragmentação, simulacros e desconfiança em metanarrativas. Na cultura, isso se manifesta no pastiche, na ironia e no colapso de hierarquias entre alta cultura e cultura popular. Socialmente, reflete-se na crise das instituições tradicionais e na multiplicação de identidades fluidas.', 2, NOW(), NOW()),
('Características', 'Entre as principais características da condição pós-moderna estão: a desmaterialização (substituição do real por signos), a temporalidade fragmentada, o fim das utopias políticas totais, a estetização da vida cotidiana, e o predomínio da cultura do espetáculo. A internet e as mídias digitais aceleraram muitas dessas tendências, criando um mundo de realidades virtuais e identidades múltiplas.', 2, NOW(), NOW()),
('Impacto Social', 'Na sociedade pós-moderna, observamos a erosão de autoridades tradicionais (como escola, família, Estado), a mercantilização de todas as esferas da vida, e o surgimento de novas formas de sociabilidade baseadas em redes digitais. Isso gera tanto novas liberdades quanto novas formas de controle, como o capitalismo de vigilância e a governamentalidade algorítmica.', 2, NOW(), NOW()),
('Debates Atuais', 'Atualmente, discute-se se já teríamos entrado em uma fase "pós-pós-moderna" ou se a pós-modernidade se aprofundou. Alguns teóricos argumentam que crises globais como mudanças climáticas e pandemias estão levando a um retorno de narrativas totalizantes, enquanto outros veem na cultura meme e na realidade pós-verdade a radicalização da condição pós-moderna.', 2, NOW(), NOW()),

-- Contents for 'Ativismo Digital' (item_id 3)
('Novas Formas', 'O ativismo digital transformou radicalmente as práticas de mobilização social, permitindo ações globais coordenadas em tempo real. Plataformas como Twitter e Telegram tornaram-se espaços de organização, enquanto táticas como hacktivismo e hashtag activism criam novas formas de pressão política. Movimentos como Primavera Árabe, Occupy e Black Lives Matter demonstraram o poder dessas ferramentas, mas também revelaram seus limites frente à repressão estatal e à vigilância digital.', 3, NOW(), NOW()),
('Ferramentas', 'Ativistas contemporâneos utilizam um arsenal digital que inclui: criptografia para comunicação segura (Signal, PGP), plataformas de financiamento coletivo, ferramentas de verificação de fatos, mapas colaborativos de protestos, e tecnologias de anonimização como Tor. Essas ferramentas permitem contornar censuras, mas também criam dependência de corporações tecnológicas cujos interesses nem sempre alinham-se com as causas ativistas.', 3, NOW(), NOW()),
('Desafios', 'Entre os principais desafios do ativismo digital estão: a vigilância estatal e corporativa, a desinformação e deepfakes usados para descreditar movimentos, a "slacktivism" (ativismo de baixo comprometimento), e a dificuldade de traduzir engajamento online em mudanças estruturais offline. Além disso, a infraestrutura digital consome recursos naturais e depende de cadeias produtivas exploratórias, criando contradições éticas.', 3, NOW(), NOW()),
('Casos de Estudo', 'Podemos analisar casos como: o uso do WhatsApp nas eleições brasileiras, o papel do TikTok em protestos globais, a censura a ativistas na China através do Great Firewall, e as táticas do Anonymous. Cada caso revela diferentes facetas das possibilidades e limitações do ativismo na era digital, mostrando como a tecnologia amplifica tanto a resistência quanto o controle.', 3, NOW(), NOW()),

-- Contents for 'Feminismo 4.0' (item_id 4)
('Evolução Histórica', 'O chamado Feminismo 4.0 representa a quarta onda do movimento, caracterizada pela interseccionalidade radical e pelo uso intensivo de tecnologias digitais. Se a primeira onda lutou por direitos básicos, a segunda pela libertação sexual, e a terceira pela diversidade, a quarta onda enfrenta desafios como assédio online, deepnudes, algoritmos sexistas e a violência digital de gênero. Plataformas como Twitter tornaram-se arenas de disputa, com hashtags como #MeToo ganhando escala global.', 4, NOW(), NOW()),
('Táticas Atuais', 'As feministas 4.0 desenvolvem táticas inovadoras como: criação de redes de apoio online, desenvolvimento de apps contra violência, uso de data activism para expor desigualdades, pressão sobre plataformas digitais para moderar conteúdo misógino, e produção de contra-narrativas em formatos como podcasts e threads. A luta agora inclui a governança da internet e o direito ao esquecimento digital para vítimas.', 4, NOW(), NOW()),
('Críticas', 'Alguns setores criticam o Feminismo 4.0 por seu excessivo foco no cultural em detrimento do econômico, por gerar polarizações improdutivas em redes sociais, e por depender de plataformas capitalistas que lucram com o conflito. Outros apontam que o movimento ainda não conseguiu incluir adequadamente mulheres de classes baixas e regiões periféricas do globo, reproduzindo privilégios digitais.', 4, NOW(), NOW()),
('Futuro', 'Os desafios futuros incluem: regular a inteligência artificial sexista, combater a violência digital transfeminista, criar alternativas tecnológicas feministas fora das Big Techs, e articular o online com lutas por direitos reprodutivos, igualdade salarial e divisão sexual do trabalho. O feminismo precisa hackear o sistema tecnopatriarcal sem ser cooptado por ele.', 4, NOW(), NOW()),

-- Contents for 'Durkheim e Fato' (item_id 5)
('Fato Social', 'Para Durkheim, fatos sociais são maneiras de agir, pensar e sentir exteriores ao indivíduo, dotadas de poder coercitivo. Eles existem independentemente das vontades individuais e se impõem através de sanções ou constrangimentos. Exemplos incluem normas jurídicas, costumes morais e até mesmo formas de linguagem. Na era digital, podemos pensar em algoritmos de redes sociais como novos fatos sociais que moldam nosso comportamento.', 5, NOW(), NOW()),
('Características', 'Durkheim estabeleceu três características dos fatos sociais: exterioridade (existem fora da consciência individual), coercitividade (exercem pressão sobre os indivíduos), e generalidade (são coletivos, não particulares). Esses critérios nos ajudam a distinguir fenômenos verdadeiramente sociais de meros comportamentos individuais agregados.', 5, NOW(), NOW()),
('Método', 'O estudo dos fatos sociais exige, segundo Durkheim, que o sociólogo trate os fenômenos sociais como "coisas", ou seja, com objetividade científica, livre de preconceitos. Isso implica afastar-se das pré-noções, definir claramente os fatos estudados, e buscar explicações sociais para fenômenos sociais, não reduzi-los a explicações psicológicas ou biológicas.', 5, NOW(), NOW()),
('Atualidade', 'O conceito de fato social permanece relevante para analisar fenômenos contemporâneos como viralizações digitais, padrões de consumo globalizados, ou a adesão a modismos tecnológicos. As plataformas digitais criam novas formas de coercitividade social, como os algoritmos que padronizam comportamentos ou a pressão por constante engajamento online.', 5, NOW(), NOW()),

-- Contents for 'Marx e Alienação' (item_id 6)
('Conceito', 'Para Marx, alienação refere-se ao processo pelo qual o trabalhador se torna estranho ao produto de seu trabalho, à atividade produtiva, a si mesmo como ser genérico, e aos outros trabalhadores. No capitalismo industrial, o trabalhador não se reconhece no que produz, que é apropriado pelo capitalista, transformando-se em algo hostil que domina seu criador. Na era digital, novas formas de alienação surgem com a precarização do trabalho via apps e a coisificação das relações sociais.', 6, NOW(), NOW()),
('Quatro Formas', 'Marx descreveu quatro dimensões da alienação: 1) do produto do trabalho (que não pertence ao trabalhador), 2) do ato de produção (trabalho como mero meio de sobrevivência), 3) do ser genérico (o homem se afasta de seu potencial criativo), e 4) dos outros homens (relações tornam-se mediadas pelo mercado). Essas formas se intensificam no capitalismo cognitivo atual.', 6, NOW(), NOW()),
('Atualização', 'Teóricos contemporâneos atualizam o conceito para incluir a alienação digital: alienação dos dados pessoais (que geram lucro para terceiros), do tempo de atenção (monetizado por plataformas), e até mesmo das emoções (exploradas pelo capitalismo afetivo). O trabalho em plataformas digitais reproduz em nova escala a separação entre trabalhador e controle sobre o processo produtivo.', 6, NOW(), NOW()),
('Superação', 'Para Marx, a superação da alienação exigiria a abolição da propriedade privada dos meios de produção e a construção de uma sociedade comunista onde os trabalhadores controlassem coletivamente o processo produtivo. Hoje, debates sobre renda básica universal, economia colaborativa e plataformas cooperativistas buscam respostas para as novas alienações do capitalismo digital.', 6, NOW(), NOW()),

-- Contents for 'Grafite como Arte' (item_id 7)
('História', 'O grafite emergiu nas décadas de 1960-70 nos subúrbios de Nova York como expressão de grupos marginalizados, especialmente jovens afro-americanos e latinos. Inicialmente visto como vandalismo, foi gradualmente reconhecido como forma artística legítima, com nomes como Basquiat, Banksy e Kobra conquistando espaços em galerias. Essa trajetória reflete lutas por reconhecimento cultural e direito à cidade.', 7, NOW(), NOW()),
('Técnicas', 'Artistas de grafite desenvolveram técnicas específicas como uso de sprays com diferentes bicos, stencils para imagens detalhadas, efeitos 3D, e integração com arquitetura urbana. O estilo varia desde tags simples até murais complexos, incorporando elementos de pop art, surrealismo e design gráfico. A evolução das tintas e materiais permitiu maior durabilidade e riqueza cromática.', 7, NOW(), NOW()),
('Significado', 'Como arte pública, o grafite democratiza o acesso à cultura, transformando espaços urbanos cinzas em galerias a céu aberto. Ele documenta conflitos sociais, homenageia figuras locais, e provoca reflexões sobre temas como desigualdade e meio ambiente. Em muitas cidades, tornou-se atração turística e elemento de identidade cultural.', 7, NOW(), NOW()),
('Controvérsias', 'Apesar do reconhecimento artístico, persistem tensões entre grafite legal (autorizado) e ilegal, entre apropriação cultural e autenticidade, e entre mercantilização e contestação. Projetos de "gentrificação artística" usam grafite para valorizar imóveis, enquanto artistas de rua lutam por espaços autônomos fora do circuito institucional.', 7, NOW(), NOW()),

-- Contents for 'Tribos Urbanas' (item_id 8)
('Definição', 'Tribos urbanas são grupos identitários que se formam em contextos metropolitanos, caracterizados por estilos de vida, códigos estéticos e valores compartilhados. Diferentemente de classes ou estratos sociais, essas tribos são escolhidas afetivamente pelos indivíduos, como punks, góticos, hipsters ou otakus. Elas oferecem pertencimento em sociedades complexas onde identidades tradicionais se fragmentam.', 8, NOW(), NOW()),
('Características', 'As tribos urbanas tipicamente desenvolvem: um estilo visual distinto (moda, tatuagens, penteados), gostos musicais específicos, linguajar próprio, espaços de sociabilidade (baladas, cafés, eventos), e uma ética compartilhada. Na era digital, essas tribos se organizam em comunidades online, mantendo simultaneamente territórios físicos nas cidades.', 8, NOW(), NOW()),
('Funções', 'Esses grupos cumprem funções psicossociais importantes: proporcionam identidade a jovens em transição, criam redes de apoio contra a massificação, e permitem experimentação com papéis sociais. Ao mesmo tempo, podem gerar conformismo dentro do grupo e conflitos com outras tribos, reproduzindo dinâmicas de exclusão.', 8, NOW(), NOW()),
('Transformações', 'Com as redes sociais, as tribos urbanas tornaram-se mais fluidas e globais. Estilos que antes levavam anos para se difundir agora viralizam em semanas, e os indivíduos transitam entre múltiplas tribos. Alguns teóricos argumentam que estamos passando de "tribos" para "redes pessoais" como forma principal de organização identitária.', 8, NOW(), NOW()),

-- Contents for 'LGBTQ+ Hoje' (item_id 9)
('Panorama Atual', 'O movimento LGBTQ+ contemporâneo enfrenta um cenário paradoxal: conquistas legais históricas (como casamento igualitário) coexistem com retrocessos em vários países e o surgimento de novas formas de violência. A visibilidade sem precedentes na mídia e política contrasta com o aumento de crimes de ódio e legislações anti-gênero. A comunidade se globalizou, mas enfrenta desafios específicos em cada contexto cultural.', 9, NOW(), NOW()),
('Novas Frentes', 'Além das lutas tradicionais por direitos civis, o movimento hoje se dedica a: combater a LGBTQ+fobia digital, garantir acesso à saúde específica (especialmente para pessoas trans), enfrentar a instrumentalização política de pautas identitárias, e incluir interseccionalidades como raça, classe e deficiência. A neurodiversidade também entra na agenda.', 9, NOW(), NOW()),
('Tecnologia', 'Aplicativos de encontros transformaram as sociabilidades LGBTQ+, criando novos espaços seguros mas também novas formas de solidão e objetificação. Plataformas como TikTok permitem ativismo criativo, enquanto deepfakes e discursos de ódio algorítmicos representam ameaças. A comunidade desenvolve suas próprias tecnologias, como apps de segurança para encontros.', 9, NOW(), NOW()),
('Desafios', 'Entre os principais desafios atuais estão: a divisão entre assimilacionistas e radicais, a comercialização do Pride por corporações, o acesso desigual a direitos globais, e o cuidado com uma geração mais jovem que sofre com altos índices de depressão e suicídio. A pandemia exacerbou vulnerabilidades específicas da comunidade.', 9, NOW(), NOW()),

-- Contents for 'Feminismo Negro' (item_id 10)
('Fundamentos', 'O feminismo negro surge da constatação de que as experiências de mulheres negras não são adequadamente representadas nem pelo feminismo branco majoritário nem pelos movimentos negros masculinizados. Pensadoras como bell hooks, Angela Davis e Sueli Carneiro desenvolveram análises interseccionais que mostram como raça, gênero e classe se articulam na opressão específica das mulheres negras.', 10, NOW(), NOW()),
('Contribuições', 'Entre as contribuições únicas do feminismo negro estão: o conceito de "matriz de dominação" (sistemas interligados de opressão), a valorização do conhecimento produzido na experiência vivida, a crítica ao universalismo feminista branco, e propostas de organização comunitária baseadas em afetos e cuidados. Essas ideias influenciaram toda a teoria social contemporânea.', 10, NOW(), NOW()),
('Ativismo', 'No Brasil, o feminismo negro se expressa em coletivos periféricos, grupos de mães, empreendedoras negras, e iniciativas como marchas e ocupações culturais. A luta por políticas públicas específicas, contra a violência obstétrica e o genocídio da juventude negra, e por representação midiática são centrais. A internet amplificou essas vozes, mas também expôs ativistas a ataques racistas.', 10, NOW(), NOW()),
('Desdobramentos', 'Recentemente, o feminismo negro tem se dedicado a: combater o encarceramento em massa de mulheres negras, garantir titulação de terras quilombolas, desenvolver epistemologias decoloniais, e criar alternativas econômicas solidárias. A saúde mental da mulher negra em sociedades racistas também se tornou pauta central.', 10, NOW(), NOW()),

-- Contents for 'Privilégio Branco' (item_id 11)
('Definição', 'Privilégio branco refere-se às vantagens estruturais que pessoas brancas desfrutam em sociedades racialmente hierarquizadas, independentemente de sua classe, gênero ou intenção individual. Como um sistema de benefícios não-escritos, ele se manifesta desde maior probabilidade de ser contratado até ausência de vigilância em lojas. Peggy McIntosh popularizou o conceito com sua metáfora da "mochila invisível" de privilégios.', 11, NOW(), NOW()),
('Manifestações', 'O privilégio branco aparece em estatísticas de renda, educação, violência policial e representação midiática. Ele se expressa também em microinterações: não ter a fala interrompida, ver sua cultura como norma universal, ou não ser tomado como representante de toda sua "raça". Na era digital, algoritmos de reconhecimento facial evidenciam esses privilégios técnicos.', 11, NOW(), NOW()),
('Desafios', 'Reconhecer o privilégio branco envolve superar resistências como a ideologia da "democracia racial", o mito da meritocracia, e o desconforto de confrontar vantagens pessoais. Muitas vezes, há uma reação defensiva que interpreta a discussão sobre privilégios como acusação pessoal, quando na verdade se trata de analisar estruturas coletivas.', 11, NOW(), NOW()),
('Ação', 'Pessoas brancas aliadas podem usar seu privilégio para: amplificar vozes não-brancas, confrontar racismos cotidianos, apoiar políticas afirmativas, e desmontar mecanismos institucionais de exclusão. Isso requer autoeducação constante, disposição para errar e aprender, e renúncia a posições de protagonismo em espaços de luta antirracista.', 11, NOW(), NOW()),

-- Contents for 'Mobilidade Social' (item_id 12)
('Conceito', 'Mobilidade social refere-se à capacidade dos indivíduos de mudarem sua posição socioeconômica ao longo da vida ou entre gerações. Ela pode ser vertical (mudança de classe), horizontal (mudança de ocupação sem alteração de status), ou intergeracional (comparação com os pais). Sociedades com alta mobilidade são consideradas mais justas, pois permitem que talentos emergentes independentemente de origem.', 12, NOW(), NOW()),
('Fatores', 'Entre os principais fatores que influenciam a mobilidade social estão: qualidade da educação pública, acesso a saúde básica, estrutura do mercado de trabalho, políticas de redistribuição de renda, e capital social (redes de relacionamento). No Brasil, estudos mostram que leva em média nove gerações para que descendentes de famílias pobres atinjam a renda média.', 12, NOW(), NOW()),
('Desafios', 'A mobilidade social enfrenta novos obstáculos na era digital: a automação ameaça empregos tradicionais de ascensão, a educação online de qualidade é inacessível para muitos, e plataformas digitais criam formas precarizadas de trabalho. Simultaneamente, a internet oferece novas oportunidades de aprendizagem e empreendedorismo para quem tem acesso e habilidades digitais.', 12, NOW(), NOW()),
('Políticas', 'Para aumentar a mobilidade, especialistas recomendam: investimento em educação infantil de qualidade, programas de primeira empregos, tributação progressiva, moradia acessível, e combate a discriminações estruturais. Experiências como renda básica universal também são testadas como forma de criar um piso mínimo para a mobilidade ascendente.', 12, NOW(), NOW()),

-- Contents for 'VPNs Avançadas' (item_id 13)
('Funcionamento', 'VPNs (Redes Privadas Virtuais) criam túneis criptografados entre dispositivos e servidores remotos, mascarando o tráfego original e ocultando o endereço IP real do usuário. As versões avançadas incorporam técnicas como double VPN (criptografia em cascata), servidores RAM-only (que não armazenam dados), e protocolos como WireGuard® que combinam velocidade e segurança. Essas ferramentas são essenciais para jornalistas, ativistas e profissionais em regimes censuradores.', 13, NOW(), NOW()),
('Aplicações', 'Além de privacidade, VPNs avançadas permitem: acesso a conteúdo georestrito sem deixar rastros, proteção em redes Wi-Fi públicas, bypass de censura governamental, e separação segura de tráfegos profissionais/pessoais. Empresas as usam para proteger comunicações remotas, enquanto indivíduos as utilizam contra vigilância massiva e throttling de ISPs.', 13, NOW(), NOW()),
('Limitações', 'VPNs não são panaceias: podem reduzir velocidade de conexão, serem bloqueadas por serviços (como Netflix), e dar falsa sensação de anonimato (o provedor VPN ainda vê seu tráfego). Alguns países criminalizam seu uso, e serviços gratuitos muitas vezes monetizam dados dos usuários. A escolha de jurisdição do provedor é crucial para proteção legal.', 13, NOW(), NOW()),
('Futuro', 'Novos desenvolvimentos incluem VPNs descentralizadas baseadas em blockchain, integração com TOR para múltiplas camadas de anonimato, e soluções hardware-based como roteadores pré-configurados. A guerra tecnológica entre censura e contornamento impulsiona inovações constantes nessa área.', 13, NOW(), NOW()),

-- Contents for '2FA Eficaz' (item_id 14)
('Tipos', 'A autenticação em dois fatores (2FA) eficaz vai além de SMS, utilizando métodos como: aplicativos autenticadores (Google Authenticator, Authy), chaves físicas de segurança (YubiKey), notificações push, ou biometria comportamental. Cada método tem trade-offs entre conveniência e segurança - chaves físicas são as mais seguras contra phishing, enquanto apps equilibram praticidade e proteção.', 14, NOW(), NOW()),
('Implementação', 'Para 2FA robusto, recomenda-se: ativar em todos serviços críticos (e-mail principal, bancos, redes sociais), usar métodos diferentes para contas distintas, ter códigos de backup impressos em local seguro, e registrar múltiplos dispositivos de autenticação. Contas privilegiadas (admin) devem exigir 2FA em cada login, não apenas em dispositivos novos.', 14, NOW(), NOW()),
('Ataques', 'Mesmo com 2FA, ataques como SIM swapping (clonagem de chip), man-in-the-middle, e engenharia social podem burlar proteções fracas. Soluções avançadas como FIDO2/WebAuthn usam criptografia de chave pública para resistir a phishing, enquanto biometria multimodal combina múltiplos fatores fisiológicos.', 14, NOW(), NOW()),
('Tendências', 'O futuro do 2FA inclui: autenticação sem senha (passwordless), padrões como FIDO Alliance para interoperabilidade, e integração com wallets digitais. A inteligência artificial também permite autenticação contínua baseada em padrões de comportamento, reduzindo dependência de etapas discretas de login.', 14, NOW(), NOW()),

-- Contents for 'Teste de Invasão' (item_id 15)
('Metodologia', 'Testes de invasão (pentests) seguem metodologias estruturadas como PTES (Penetration Testing Execution Standard), envolvendo: reconhecimento (coleta de informações), varredura (identificação de vulnerabilidades), exploração (tentativa de acesso), pós-exploração (manutenção de acesso), e relatório. Pentesters profissionais usam abordagem ética, com consentimento por escrito e cuidado para não causar danos reais aos sistemas.', 15, NOW(), NOW()),
('Ferramentas', 'O arsenal inclui: Nmap (varredura de redes), Burp Suite (testes web), Metasploit (exploração de vulnerabilidades), Wireshark (análise de tráfego), e frameworks como Kali Linux. Pentesters avançados desenvolvem scripts personalizados e técnicas de engenharia social, simulando ataques reais sem depender apenas de ferramentas automatizadas.', 15, NOW(), NOW()),
('Certificações', 'Profissionais buscam certificações como OSCP (Offensive Security Certified Professional), CEH (Certified Ethical Hacker), ou eJPT, que validam habilidades práticas. O mercado valoriza pentesters com conhecimento em normas como ISO 27001, PCI-DSS e OWASP, capazes de alinhar testes aos riscos de negócio reais.', 15, NOW(), NOW()),
('Desafios', 'Pentesters enfrentam dilemas como: balancear profundidade do teste com tempo orçado, lidar com sistemas críticos onde explorações podem causar indisponibilidade, e comunicar vulnerabilidades complexas para gestores não-técnicos. A evolução para Red Teaming (simulações de ataques avançados persistentes) representa o próximo nível de maturidade.', 15, NOW(), NOW()),

-- Contents for 'OWASP Top 10' (item_id 16)
('Visão Geral', 'A lista OWASP Top 10 cataloga as dez vulnerabilidades web mais críticas, atualizada periodicamente por especialistas globais. A edição 2021 inclui: injeções (SQL, comandos), falhas de autenticação, exposição de dados sensíveis, configurações inseguras, e lógica de negócio falha. Cada item vem com exemplos reais, impactos potenciais, e melhores práticas de prevenção.', 16, NOW(), NOW()),
('Mudanças', 'A versão 2021 trouxe novidades como: "Server-Side Request Forgery" (SSRF) entrando pela primeira vez, "Insecure Design" focando em falhas arquiteturais, e "Software and Data Integrity Failures" refletindo ataques à cadeia de suprimentos. A remoção de "XML External Entities" (XXE) mostra progresso na correção desse vetor.', 16, NOW(), NOW()),
('Impacto', 'Empresas usam o OWASP Top 10 para priorizar investimentos em segurança, enquanto frameworks como NIST e ISO 27001 a referenciam. Certificações de desenvolvedores (como Secure Code Warrior) testam conhecimento dessas vulnerabilidades. O projeto democratiza conhecimento técnico, permitindo que startups protejam sistemas sem orçamentos elevados.', 16, NOW(), NOW()),
('Críticas', 'Alguns especialistas argumentam que a lista simplifica excessivamente riscos complexos, foca demais em aplicações web tradicionais (ignorando APIs modernas e serverless), e atualiza-se lentamente para ameaças emergentes. Alternativas como "OWASP API Security Top 10" surgem para cobrir essas lacunas.', 16, NOW(), NOW()),

-- Contents for 'Clean Code' (item_id 17)
('Princípios', 'Clean Code (Código Limpo) é uma filosofia de programação que enfatiza clareza, manutenibilidade e simplicidade. Seus princípios incluem: nomes significativos (variáveis, funções), funções pequenas com única responsabilidade, ausência de duplicação (DRY), tratamento explícito de erros, e testes automatizados. O objetivo é criar código que humanos entendam facilmente, não apenas máquinas.', 17, NOW(), NOW()),
('Benefícios', 'Código limpo reduz bugs, facilita colaboração em equipe, permite refatoração segura, e diminui custos de manutenção a longo prazo. Estudos mostrem que até 80% do custo total de software vem da fase de manutenção, tornando investimento em qualidade inicial altamente rentável. Sistemas legados com código limpo são mais fáceis de modernizar.', 17, NOW(), NOW()),
('Técnicas', 'Práticas como: revisão de código em pares, padronização via linters (ESLint, Pylint), refatoração contínua, e documentação embutida (via docstrings) ajudam a manter limpeza. Metodologias como TDD (Test-Driven Development) naturalmente incentivam código mais modular e testável. Ferramentas de análise estática (SonarQube) identificam "code smells".', 17, NOW(), NOW()),
('Desafios', 'Equipes enfrentam obstáculos como: pressão por prazos curtos que incentivam "quick and dirty", resistência a mudanças culturais, e dificuldade em medir ROI da qualidade de código. Projetos com alta rotatividade de desenvolvedores sofrem especialmente quando não há padrões claros documentados.', 17, NOW(), NOW()),

-- Contents for 'Python Moderno' (item_id 18)
('Recursos', 'Python moderno (3.8+) introduziu features poderosas como: assignment expressions (:=), positional-only parameters, type hints avançados, e melhorias de desempenho (subinterpreters). Context managers async, pattern matching (estrutural), e zoneinfo para timezones refletem necessidades contemporâneas. A linguagem mantém sua filosofia de legibilidade enquanto incorpora paradigmas complexos.', 18, NOW(), NOW()),
('Ecossistema', 'Além da biblioteca padrão, o ecossistema Python moderno inclui: FastAPI para APIs rápidas, Poetry para gerenciamento de dependências, Pydantic para validação de dados, e ferramentas como PyTorch para ML. Jupyter Notebooks evoluíram para JupyterLab, enquanto soluções como PyScript permitem rodar Python no browser.', 18, NOW(), NOW()),
('Boas Práticas', 'Desenvolvedores modernos adotam: type checking estático com mypy, virtual environments nativos, formatação automática via Black, e testes com pytest. Arquiteturas assíncronas (asyncio) e uso eficiente de recursos são prioritários, especialmente em microsserviços e edge computing. O PEP 8 permanece como guia de estilo, mas com adaptações pragmáticas.', 18, NOW(), NOW()),
('Futuro', 'As próximas versões prometem: melhor desempenho via otimizações no bytecode, mais features para programação concorrente, e integração com WebAssembly. Projetos como Cinder (Meta) exploram JIT compilation, enquanto CPython trabalha em reduzir GIL limitations. Python consolida-se como lingua franca para dados, automação e prototyping rápido.', 18, NOW(), NOW()),

-- Contents for 'AWS Básico' (item_id 19)
('Serviços Essenciais', 'AWS oferece mais de 200 serviços, mas iniciantes devem dominar: EC2 (máquinas virtuais), S3 (armazenamento objeto), RDS (bancos relacionais), Lambda (computação serverless), e IAM (gerenciamento de acesso). Entender billing e tags é crucial para evitar custos surpresa. O Free Tier permite experimentação inicial sem custos.', 19, NOW(), NOW()),
('Conceitos-chave', 'Novatos precisam compreender: regiões e zonas de disponibilidade, modelos de responsabilidade compartilhada, arquitetura well-architected (os cinco pilares), e diferenças entre infraestrutura como serviço (IaaS), plataforma (PaaS) e software (SaaS). O console web é acessível, mas a CLI e CDK são mais poderosas para automação.', 19, NOW(), NOW()),
('Segurança', 'Boas práticas iniciais incluem: configurar MFA na conta root, usar políticas IAM mínimas necessárias, habilitar CloudTrail para auditoria, e não expor credenciais em repositórios. Serviços como GuardDuty detectam ameaças, enquanto AWS Organizations ajuda a gerenciar múltiplas contas com segurança.', 19, NOW(), NOW()),
('Certificação', 'A AWS Certified Cloud Practitioner valida conhecimento básico em nuvem e serviços AWS. Preparação envolve cursos gratuitos da AWS Skill Builder, whitepapers arquiteturais, e testes práticos. Essa base permite avançar para certificações associadas como Solutions Architect ou Developer.', 19, NOW(), NOW()),

-- Contents for 'Serverless' (item_id 20)
('Fundamentos', 'Computação serverless permite executar código (como AWS Lambda) sem gerenciar servidores, com cobrança por tempo de execução real. Benefícios incluem escalabilidade automática, alta disponibilidade nativa, e redução de overhead operacional. Use cases típicos são: APIs leves, processamento de eventos, e automações pontuais.', 20, NOW(), NOW()),
('Desafios', 'Apesar da simplicidade, serverless traz complexidades: cold starts (latência inicial), debugging distribuído, limites de tempo/memória, e acoplamento a serviços cloud específicos. Aplicações complexas exigem orquestração (Step Functions) e padrões como Event Sourcing para gerenciar estado.', 20, NOW(), NOW()),
('Ferramentas', 'Frameworks como Serverless e SAM simplificam deploy, enquanto soluções como AWS X-Ray ajudam a monitorar performance. Bibliotecas específicas (aws-lambda-powertools) implementam boas práticas. Para desenvolvimento local, ferramentas como LocalStack emulam ambiente AWS serverless offline.', 20, NOW(), NOW()),
('Futuro', 'O ecossistema evolui para: maior tempo máximo de execução, suporte a mais linguagens, melhores ferramentas observabilidade, e integração com edge computing. Conceitos como serverless containers (AWS Fargate) e databases serverless (Aurora Serverless) expandem o modelo para novas cargas de trabalho.', 20, NOW(), NOW()),

-- Contents for 'SD-WAN' (item_id 21)
('Conceito', 'SD-WAN (Software-Defined Wide Area Network) aplica princípios de virtualização a redes corporativas, separando plano de controle (gerenciamento centralizado) do plano de dados (tráfego local). Isso permite roteamento inteligente entre múltiplos links (MPLS, LTE, broadband) baseado em políticas de negócio, QoS e custo.', 21, NOW(), NOW()),
('Vantagens', 'Comparado a WAN tradicional, SD-WAN oferece: redução de custos (usa links baratos para tráfego não-crítico), agilidade (provisionamento via software), resiliência (failover automático), e visibilidade centralizada. Empresas com múltiplas filiais ou migrando para nuvem são principais beneficiárias.', 21, NOW(), NOW()),
('Implementação', 'Soluções como Cisco SD-WAN, VMware Velocloud e Fortinet Secure SD-WAN combinam appliances físicos (CPE) com controladores em nuvem. A migração requer inventário de aplicações (para definir políticas), avaliação de links existentes, e possível upgrade de branch offices. Segurança integrada (ZTNA, firewall) é diferencial.', 21, NOW(), NOW()),
('Tendências', 'O futuro do SD-WAN inclui: integração com SASE (Secure Access Service Edge), suporte a 5G como link primário, e maior uso de AIOps para otimização preditiva. A convergência com redes 5G privadas e edge computing criará arquiteturas híbridas ainda mais flexíveis.', 21, NOW(), NOW()),

-- Contents for 'Zero Trust' (item_id 22)
('Princípios', 'Zero Trust é um modelo de segurança que assume que nenhum usuário ou dispositivo deve ser confiável por padrão, mesmo dentro da rede corporativa. Seus pilares são: verificação contínua, acesso mínimo privilegiado, e microssegmentação. Diferente do modelo "castelo e fosso", Zero Trust protege dados onde quer que estejam - nuvem, endpoints ou data centers.', 22, NOW(), NOW()),
('Componentes', 'Implementar Zero Trust requer: IAM robusto (com MFA), segmentação de rede granular, inspeção de tráfego east-west, e políticas baseadas em contexto (localização, horário, risco do dispositivo). Soluções como Zscaler Private Access e Google BeyondCorp oferecem frameworks prontos, enquanto NIST SP 800-207 fornece diretrizes.', 22, NOW(), NOW()),
('Desafios', 'Adoção enfrenta obstáculos como: complexidade em ambientes legados, resistência cultural à verificação constante, e necessidade de visibilidade unificada. Migrações para nuvem aceleram a adoção, mas exigem reestruturação de políticas de acesso. ROI é medido em redução de superfície de ataque e velocidade de detecção de breaches.', 22, NOW(), NOW()),
('Futuro', 'Evoluções incluem: integração com AI para avaliação contínua de risco, expansão para IoT/OT, e padrões abertos para interoperabilidade. O conceito está se expandindo para Zero Trust Data Security (proteção baseada em classificação de dados), não apenas controle de acesso.', 22, NOW(), NOW()),

-- Contents for 'Smart Home' (item_id 23)
('Segurança', 'Dispositivos IoT para smart homes frequentemente têm vulnerabilidades como senhas padrão, firmware desatualizado, e comunicações não criptografadas. Boas práticas incluem: mudar credenciais padrão, segmentar rede (VLAN separada), desativar features não usadas, e monitorar tráfego suspeito. Certificações como ioXt garantem padrões mínimos.', 23, NOW(), NOW()),
('Privacidade', 'Assistentes virtuais e câmeras inteligentes coletam dados sensíveis (voz, imagens internas). Usuários devem: revisar permissões, desativar gravações desnecessárias, optar por processamento local quando possível, e entender políticas de retenção de dados. Leis como GDPR dão direito à exclusão desses dados.', 23, NOW(), NOW()),
('Protocolos', 'Padrões concorrentes como Matter (ex-Project CHIP), Zigbee, Z-Wave e Thread prometem maior interoperabilidade e segurança. Dispositivos com suporte a atualizações OTA (Over-The-Air) são preferíveis, pois recebem patches de segurança. Hubs centralizados (Home Assistant) oferecem mais controle que soluções cloud-dependentes.', 23, NOW(), NOW()),
('Automação', 'Rotinas automatizadas (como iluminação e climatização) devem ter fallbacks manuais para evitar lockouts digitais. Sistemas críticos (fechaduras, alarmes) exigem redundância e backup de energia. A automação excessiva pode criar complexidade desnecessária - simplicidade muitas vezes é mais segura.', 23, NOW(), NOW()),

-- Contents for 'IoT Protocols' (item_id 24)
('Comparação', 'Protocolos IoT diferem em: consumo energético, alcance, taxa de dados, segurança nativa e custo. MQTT é leve para telemetria, CoAP funciona bem em redes restritas, AMQP suporta mensagens complexas, enquanto LoRaWAN cobre longas distâncias com baixa energia. Escolha depende do use case específico - industrial, urbano ou residencial.', 24, NOW(), NOW()),
('Segurança', 'Muitos protocolos IoT foram criados sem segurança robusta. Mitigações incluem: usar TLS/DTLS mesmo quando opcional, implementar controle de acesso granular, rotacionar chaves regularmente, e monitorar padrões anômalos. Padrões emergentes como OSCORE trazem criptografia fim-a-fim para ambientes restritos.', 24, NOW(), NOW()),
('Tendências', 'Novos desenvolvimentos incluem: 5G RedCap para IoT de média complexidade, Wi-Fi 6 para alta densidade de dispositivos, e Matter para padronização residencial. Edge AI está levando a protocolos mais inteligentes que filtram dados localmente antes da transmissão, economizando banda e melhorando privacidade.', 24, NOW(), NOW()),
('Implementação', 'Projetar redes IoT requer: análise de trade-offs (latência vs. energia), testes de interferência em ambiente real, e planejamento para atualizações remotas. Gateways intermediários podem traduzir entre protocolos diferentes, enquanto gerenciamento centralizado (como Azure IoT Hub) simplifica operações em escala.', 24, NOW(), NOW()),

-- Contents for 'Metasploit' (item_id 25)
('Framework', 'Metasploit é um framework open-source para desenvolvimento e execução de exploits contra sistemas vulneráveis. Sua estrutura modular inclui: módulos de exploração, payloads (código executado após exploração), encoders (para evadir AV), e auxiliares (scanners, fuzzers). A versão Pro adiciona features para equipes profissionais.', 25, NOW(), NOW()),
('Workflow', 'O fluxo típico envolve: identificar alvos (via nmap ou aux modules), selecionar exploit apropriado, configurar payload (como reverse shell), definir opções (portas, credenciais), e executar. Pós-exploração, módulos como mimikatz extraem credenciais, enquanto pivotagem permite avançar na rede comprometida.', 25, NOW(), NOW()),
('Defesa', 'Para se proteger contra Metasploit, organizações devem: manter sistemas atualizados, usar EDR/XDR para detecção comportamental, segmentar redes, e realizar pentests regulares. Ferramentas como Metasploit podem ser usadas defensivamente para validar controles de segurança - ethical hacking é aplicação principal.', 25, NOW(), NOW()),
('Comunidade', 'A versão community é mantida por contribuições open-source, com novos módulos frequentemente adicionados para vulnerabilidades zero-day. Recursos como Exploit-DB integram-se ao Metasploit, enquanto treinamentos como OSCP ensinam seu uso ético profissional. O framework evolui para cobrir novas tecnologias como containers e IoT.', 25, NOW(), NOW()),

-- Contents for 'Burp Suite' (item_id 26)
('Componentes', 'Burp Suite é um conjunto de ferramentas para teste de segurança web. O Professional inclui: Proxy (interceptar/modificar tráfego), Scanner (automatizado), Intruder (ataques personalizados), Repeater (modificar/reenviar requests), e Collaborator (detectar interações externas). A versão Community tem funcionalidades limitadas.', 26, NOW(), NOW()),
('Metodologia', 'Testes com Burp seguem: mapeamento de aplicação (spidering), análise de tráfego (Proxy), identificação automatizada de vulnerabilidades (Scanner), e exploração manual (Intruder/Repeater). Features como match-and-replace automatizam modificações de requests, enquanto extensões BApps ampliam funcionalidades.', 26, NOW(), NOW()),
('Casos de Uso', 'Burp é essencial para encontrar: vulnerabilidades OWASP Top 10, lógicas de negócio quebradas, problemas de controle de acesso, e vazamentos de informação. Seu scanner gera relatórios detalhados para desenvolvedores corrigirem falhas. Profissionais usam junto com ferramentas como OWASP ZAP para cobertura abrangente.', 26, NOW(), NOW()),
('Extensões', 'A API BApp permite instalar extensões como: Autorize (testar controle de acesso), Turbo Intruder (ataques high-speed), e SAML Raider (testar SSO). Desenvolvedores podem criar plugins em Python ou Ruby para automatizar testes específicos. A comunidade mantém centenas de extensões para nichos como APIs GraphQL e WebSockets.', 26, NOW(), NOW()),

-- Contents for 'Memory Dump' (item_id 27)
('Técnicas', 'Memory forensics analisa dumps de memória RAM para evidências de malware, credenciais, ou atividades maliciosas. Ferramentas como Volatility (open-source) ou Rekall permitem: extrair processos ativos, reconhecer injeções de código, recuperar arquivos mapeados, e analisar artefatos como conexões de rede e registros de teclas digitadas.', 27, NOW(), NOW()),
('Coleta', 'Criar dumps válidos requer: ferramentas especializadas (WinPmem, LiME para Linux), evitar contaminação do estado original, e documentar cadeia de custódia. Dumps completos consomem GBs - técnicas alternativas como extração seletiva (apenas heap de processo específico) podem ser mais eficientes em sistemas críticos.', 27, NOW(), NOW()),
('Análise', 'Investigadores buscam: processos ocultos (rootkits), DLLs injetadas, hooks maliciosos, e strings sensíveis (como senhas em texto claro). Técnicas avançadas incluem análise de page tables para reconstruir memória paginada, e correlacionar timestamps entre diferentes artefatos na memória.', 27, NOW(), NOW()),
('Desafios', 'Memory forensics enfrenta: criptografia de memória (como Windows Credential Guard), técnicas anti-forense (overwriting artifacts), e complexidade em sistemas modernos (containers, serverless). A ascensão de ataques fileless (que existem apenas na memória) aumenta a importância dessa disciplina.', 27, NOW(), NOW()),

-- Contents for 'Chain of Custody' (item_id 28)
('Procedimentos', 'Cadeia de custódia documenta quem manipulou evidências digitais, quando e por quê. Requer: registro detalhado (formulários padronizados), selagem física/logística (hashes criptográficos), e controle de acesso estrito. Quebras na cadeia podem invalidar evidências em tribunais - ferramentas como FTK Imager geram logs automáticos de aquisição.', 28, NOW(), NOW()),
('Padrões', 'Organizações seguem frameworks como ISO 27037 (preservação de evidências), NIST SP 800-86 (integração forense), e normas locais (como FBI CJIS). Evidências devem ser armazenadas em local seguro, com cópias íntegras (write-blockers durante aquisição) e políticas claras para destruição após caso encerrado.', 28, NOW(), NOW()),
('Automação', 'Soluções como GRR Rapid Response e osquery permitem coleta remota de evidências com cadeia de custódia digital, usando assinaturas criptográficas e logs imutáveis. Blockchain está sendo testado para registrar manipulações de forma verificável, especialmente em investigações distribuídas.', 28, NOW(), NOW()),
('Casos Complexos', 'Investigações em nuvem (multi-jurisdição), IoT (dados efêmeros), e ambientes ágeis (containers efêmeros) desafiam modelos tradicionais. Novas abordagens incluem: preservação legal em nuvem (legal hold), image forensics para microserviços, e coleta contínua em sistemas dinâmicos.', 28, NOW(), NOW()),

-- Contents for 'AES-256' (item_id 29)
('Algoritmo', 'AES (Advanced Encryption Standard) é um cifrador de bloco simétrico que processa dados em blocos de 128 bits usando chaves de 128, 192 ou 256 bits. AES-256 usa 14 rodadas de transformações (SubBytes, ShiftRows, MixColumns, AddRoundKey), com expansão de chave complexa. Seu design segue princípios de confusão e difusão para resistência a ataques.', 29, NOW(), NOW()),
('Implementação', 'Usar AES-256 corretamente requer: modo de operação apropriado (GCM para autenticação, CBC para compatibilidade), IVs únicos/não-preditivos, e gerenciamento seguro de chaves (HSMs, TPMs). Implementações devem evitar side-channel attacks (como timing attacks) - bibliotecas como OpenSSL e libsodium oferecem versões seguras.', 29, NOW(), NOW()),
('Segurança', 'AES-256 é considerado quantum-resistant - mesmo com algoritmo de Grover, computadores quânticos precisariam de 2^128 operações para quebrá-lo. Ataques práticos hoje são contra implementações (weak keys, poor randomness), não contra o algoritmo em si. NIST aprova AES-256 para informações classificadas até TOP SECRET.', 29, NOW(), NOW()),
('Aplicações', 'Além de criptografia de dados em repouso/trânsito, AES-256 é usado em: sistemas de arquivos criptografados (BitLocker), VPNs (IPsec), comunicações seguras (Signal), e até hardware (chips Secure Enclave). Sua eficiência em hardware permite uso desde servidores até dispositivos IoT com restrições.', 29, NOW(), NOW()),

-- Contents for 'RSA Basics' (item_id 30)
('Fundamentos', 'RSA é um algoritmo assimétrico baseado na dificuldade de fatorar grandes números primos. Seus parâmetros são: módulo n (produto de dois primos p,q), expoente público e (tipicamente 65537), e privado d (inverso modular de e). Mensagens são cifradas com a chave pública e decifradas com a privada - ou vice-versa para assinaturas.', 30, NOW(), NOW()),
('Boas Práticas', 'Implementações seguras requerem: tamanhos de chave ≥2048 bits (3072/4096 para longevidade), preenchimento seguro (OAEP, não PKCS#1 v1.5), e proteção contra side-channel attacks. RSA puro é lento - na prática, usa-se para trocar chaves simétricas ou assinar hashes, não cifrar dados diretamente.', 30, NOW(), NOW()),
('Limitações', 'RSA enfrenta: vulnerabilidade a computação quântica (algoritmo de Shor), degradação de desempenho com chaves grandes, e riscos se primos p,q não forem verdadeiramente aleatórios. Alternativas como ECC (curvas elípticas) oferecem segurança similar com chaves menores, mas RSA persiste por compatibilidade.', 30, NOW(), NOW()),
('Cenário Atual', 'Apesar dos desafios, RSA ainda protege a maioria das conexões HTTPS (juntamente com ECDHE para forward secrecy), assina pacotes software, e autentica dispositivos. A migração para algoritmos pós-quânticos (como NTRU, CRYSTALS-Kyber) está em curso, mas será gradual devido à base instalada.', 30, NOW(), NOW()),

-- Contents for 'SAST Tools' (item_id 31)
('Funcionamento', 'Static Application Security Testing (SAST) analisa código-fonte sem executá-lo, identificando vulnerabilidades como injeções SQL, XSS, ou uso inseguro de criptografia. Ferramentas como Checkmarx, Fortify e SonarQube usam: análise de fluxo de dados, pattern matching, e modelos de ameaça para detectar riscos durante o desenvolvimento.', 31, NOW(), NOW()),
('Integração', 'SAST eficaz requer: escaneamento em pull requests (impedir código vulnerável no main), customização de regras para contexto específico, e triagem de resultados (priorizar falsos positivos). Pipelines CI/CD modernas incorporam SAST como gate de qualidade, com ferramentas como GitLeaks prevenindo vazamentos de credenciais.', 31, NOW(), NOW()),
('Limitações', 'SAST sofre com: falsos positivos (requer revisão humana), incapacidade de detectar runtime issues, e dificuldade com linguagens dinâmicas. Análises profundas consomem tempo - abordagens como incremental scanning (apenas código modificado) e análise diferencial melhoram desempenho.', 31, NOW(), NOW()),
('Tendências', 'Inovações incluem: SAST para infra-as-code (Terraform, Kubernetes), uso de IA para reduzir falsos positivos, e integração com SCM (como GitHub Code Scanning). Ferramentas emergentes focam em linguagens modernas (Rust, Go) e frameworks cloud-native, complementando DAST e IAST.', 31, NOW(), NOW()),

-- Contents for 'CI/CD Secure' (item_id 32)
('Riscos', 'Pipelines CI/CD são alvos valiosos - comprometimento permite injeção de malware em builds oficiais. Ataques comuns exploram: secrets em logs, dependências maliciosas, runners mal configurados, e aprovações automáticas. O caso SolarWinds destacou riscos na cadeia de suprimentos de software.', 32, NOW(), NOW()),
('Proteções', 'Pipeline seguras implementam: least privilege (tokens temporários, permissões mínimas), escaneamento de dependências (Dependabot, Snyk), artefatos assinados (cosign, SBOMs), e ambientes efêmeros/isolados. Ferramentas como Tekton e GitLab oferecem features de segurança nativas, enquanto SPIFFE/SPIRE gerenciam identidades.', 32, NOW(), NOW()),
('Monitoramento', 'Além de prevenir ataques, equipes devem: auditar atividades de pipeline (quem aprovou mudanças?), monitorar desvios de baseline (novas dependências, tempos de build anômalos), e ter rollback automatizado para builds comprometidos. Soluções como Chainguard e Aqua Security focam em supply chain security.', 32, NOW(), NOW()),
('Futuro', 'Próximos passos incluem: padrões como SLSA (Supply-chain Levels for Software Artifacts), adoção de attested builds (proveniência verificável), e maior uso de confidential computing para proteger segredos durante o build. A ascensão de AI coding assistants traz novos vetores de ataque a considerar.', 32, NOW(), NOW()),

-- Contents for 'Regência Verbal' (item_id 33)
('Conceito', 'Regência verbal estuda a relação entre verbos e seus complementos, determinando se estes são ligados por preposição (regência indireta) ou não (regência direta). Verbos como "aspirar" mudam sentido conforme a regência: "aspirar o pó" (diretamente) vs "aspirar ao cargo" (com preposição). Dominar regência evita erros como "obedecer o pai" (incorreto) vs "obedecer ao pai".', 33, NOW(), NOW()),
('Classificação', 'Verbos podem ser: transitivos diretos (exigem objeto direto: "amar alguém"), transitivos indiretos (exigem preposição: "gostar de algo"), bitransitivos (dois complementos: "dar algo a alguém"), ou intransitivos (não exigem complemento: "chorar"). Alguns como "pedir" permitem ambas construções ("pedir ajuda"/"pedir por ajuda") com nuances de significado.', 33, NOW(), NOW()),
('Casos Complexos', 'Certos verbos desafiam regras simples: "perdoar" aceita ambas construções ("perdoar alguém"/"perdoar a alguém"), enquanto "querer" é direto para pessoas ("querer alguém") mas indireto para coisas ("querer a algo"). Verbos como "visar" geram controvérsias entre puristas ("visar algo") e uso consolidado ("visar a algo").', 33, NOW(), NOW()),
('Evolução', 'A regência verbal não é estática - construções como "assistir o jogo" (em vez de "assistir ao jogo") ganham aceitação pelo uso generalizado. Dicionários e gramáticas registram essas mudanças, mas contextos formais ainda privilegiam as regras tradicionais. A influência de traduções do inglês acelera algumas dessas transformações.', 33, NOW(), NOW()),

-- Contents for 'Crase' (item_id 34)
('Regras Básicas', 'A crase é a fusão da preposição "a" com o artigo feminino "a", indicada pelo acento grave (`). Ocorre antes de substantivos femininos ("vou à escola"), em locuções adverbiais femininas ("à noite"), e em expressões de modo ("à francesa"). Não se usa antes de nomes masculinos, verbos no infinitivo, ou pronomes pessoais (exceto "àquelas").', 34, NOW(), NOW()),
('Casos Especiais', 'Dúvidas comuns incluem: topônimos (usa-se em "à Bahia" mas não em "a Brasília"), palavras masculinas que antecedem femininos ("à mesma hora"), e expressões com "casa"/"terra"/"distância" (só têm crase quando especificadas: "vou à casa da mãe" vs "vou a casa"). O pronome "que" pode exigir crase ("à que custo").', 34, NOW(), NOW()),
('Testes Práticos', 'Para confirmar o uso, substitua o termo feminino por um masculino equivalente: se exigir "ao", há crase ("dedicado à música" → "dedicado ao esporte"). Outra técnica é tentar trocar por "para a" - se fizer sentido, provavelmente leva crase. Ferramentas como Revisaço automatizam essa verificação.', 34, NOW(), NOW()),
('Controvérsias', 'Algumas construções geram debate: "à medida que" (padrão) vs "a medida que" (uso consagrado), ou expressões como "a princípio"/"à princípio". A tendência moderna é simplificar o uso da crase, mas redações formais ainda exigem rigor. Dicionários eletrônicos ajudam a sanar dúvidas específicas.', 34, NOW(), NOW()),

-- Contents for 'Machado de Assis' (item_id 35)
('Estilo Literário', 'Machado de Assis (1839-1908) é celebrado por sua ironia fina, narradores não-confiáveis, e análise psicológica profunda. Sua obra divide-se em fase romântica (como "Helena") e realista/psicológica ("Memórias Póstumas de Brás Cubas"). Características únicas incluem: digressões filosóficas, intertextualidade, e metalinguagem, antecipando técnicas modernistas.', 35, NOW(), NOW()),
('Temas Recorrentes', 'Machado explorou: o caráter ilusório das aparências sociais, o egoísmo humano mascarado por convenções, a loucura como contraponto à razão, e a mobilidade social no Segundo Reinado. Seus personagens frequentemente revelam contradições entre o ser e o parecer, como Bentinho ("Dom Casmurro") ou Rubião ("Quincas Borba").', 35, NOW(), NOW()),
('Inovações', 'Considerado precursor do realismo mágico e da literatura pós-moderna, Machado quebrou convenções: "Brás Cubas" é narrado por um defunto-autor, "Dom Casmurro" constrói ambiguidade irresolúvel, e "O Alienista" satiriza a ciência. Sua linguagem mescla registros cultos e populares com maestria.', 35, NOW(), NOW()),
('Legado', 'Fundador da Academia Brasileira de Letras, Machado influenciou autores de Graciliano Ramos a Dalton Trevisan. Sua obra ganha novas interpretações: estudos pós-coloniais destacam seu olhar sobre escravidão, enquanto análises feministas revisitam personagens como Capitu. Traduções recentes o consagram como autor universal.', 35, NOW(), NOW()),

-- Contents for 'Clarice Lispector' (item_id 36)
('Estilo Único', 'Clarice Lispector (1920-1977) desenvolveu uma prosa introspectiva e poética que desafia convenções narrativas. Suas obras ("Perto do Coração Selvagem", "A Hora da Estrela") caracterizam-se por fluxo de consciência, frases fragmentadas, e mergulho em estados psicológicos liminares. A linguagem clariceana busca capturar o indizível - epifanias cotidianas que revelam abismos existenciais.', 36, NOW(), NOW()),
('Temas', 'Explorou: a solidão essencial do ser, a estranheza do familiar, a violência sob a superfície do banal, e a busca por autenticidade em um mundo de máscaras. Personagens como Macabéa ("A Hora da Estrela") ou G.H. ("A Paixão Segundo G.H.") encarnam dramas metafísicos através de vidas aparentemente insignificantes.', 36, NOW(), NOW()),
('Filosofia', 'Sua obra dialoga com existencialismo, misticismo judaico, e fenomenologia, sem se filiar a sistemas. A pergunta "quem sou?" ecoa em narrativas que desconstroem identidades fixas. Animais, objetos e espaços domésticos ganham carga metafísica, revelando o extraordinário no ordinário.', 36, NOW(), NOW()),
('Recepção', 'Inicialmente mal compreendida, Clarice tornou-se ícone feminista e literário. Sua figura pública - mulher, estrangeira, de beleza glamourosa - contrastava com a profundidade de sua escrita. Hoje, inspira adaptações para cinema, teatro e artes visuais, além de estudos acadêmicos multidisciplinares.', 36, NOW(), NOW()),

-- Contents for 'Show, Don''t Tell' (item_id 37)
('Técnica', '"Show, don''t tell" ensina a apresentar experiências através de detalhes sensoriais, ações e diálogos, em vez de resumos abstratos. Em vez de "Ela estava nervosa", mostrar: "Seus dedos tamborilavam na mesa, os olhos saltando do relógio para a porta". Isso imerge o leitor na cena, permitindo que infira emoções e significados.', 37, NOW(), NOW()),
('Aplicações', 'A técnica é útil para: caracterização indireta (revelar personagens por ações), criação de atmosfera (descrever ambientes que evocam sentimentos), e desenvolvimento de tensão (mostrar pistas em vez de anunciar perigos). Memórias e narrativas jornalísticas também se beneficiam desse enfoque mais vívido.', 37, NOW(), NOW()),
('Equilíbrio', 'Embora poderosa, a técnica não deve eliminar totalmente o "telling", que é necessário para transições, resumos de períodos longos, ou informações contextuais. O segredo está em dosar - mostrar momentos-chave e contar o que conecta esses momentos. Autores como Hemingway usaram esse equilíbrio magistralmente.', 37, NOW(), NOW()),
('Exercícios', 'Praticar através de: transformar adjetivos em cenas ("bondoso" → "ajudava vizinhos a carregar compras"), reescrever resumos como cenas dramáticas, e criar descrições que impliquem emoções sem nomeá-las. Ferramentas como "The Emotion Thesaurus" auxiliam nesse processo.', 37, NOW(), NOW()),

-- Contents for 'Fluxo de Consciência' (item_id 38)
('Origem', 'O fluxo de consciência (stream of consciousness) surgiu no modernismo, influenciado por teorias psicológicas sobre a mente associativa. Autores como Virginia Woolf ("Mrs. Dalloway"), James Joyce ("Ulysses") e William Faulkner capturam o pensamento em seu estado bruto - não-linear, fragmentado, mesclando memórias, sensações e associações livres.', 38, NOW(), NOW()),
('Técnicas', 'Para representar o fluxo mental, escritores usam: pontuação não-convencional, monólogos interiores, justaposição de tempos verbais, e rupturas sintáticas. Em Clarice Lispector, o fluxo muitas vezes culmina em epifanias; em Joyce, reproduz até os tropeços da mente pré-verbal.', 38, NOW(), NOW()),
('Desafios', 'Escrever (e ler) fluxo de consciência exige: abandonar expectativas de linearidade, tolerar ambiguidades, e capturar vozes mentais autênticas. O risco é criar textos caóticos ou autoindulgentes - o melhor fluxo equilibra espontaneidade e controle artístico.', 38, NOW(), NOW()),
('Variações', 'Técnicas relacionadas incluem: monólogo interior (mais estruturado), estilo indireto livre (narrativa em terceira pessoa que absorve a voz do personagem), e cut-up (colagem de fragmentos). Autores contemporâneos como David Foster Wallace atualizaram a técnica para a era da hiperestimulação.', 38, NOW(), NOW()),

-- Contents for 'Intertextualidade' (item_id 39)
('Conceito', 'Intertextualidade refere-se ao diálogo entre textos, onde uma obra referencia, parodia, reinterpreta ou ecoa outra. Pode ser explícita (citações, alusões) ou implícita (estruturas paralelas, arquétipos compartilhados). Desde a Bíblia até memes digitais, a cultura se constrói através dessa rede de significados compartilhados.', 39, NOW(), NOW()),
('Tipos', 'Gérard Genette classificou: paratextualidade (títulos, prefácios), metatextualidade (comentário crítico), arquitextualidade (gêneros), hipertextualidade (transformação de um texto anterior), e hipotextualidade (relação com textos-fonte). Práticas como fanfiction e remix culture são hipertextuais por excelência.', 39, NOW(), NOW()),
('Funções', 'A intertextualidade pode: homenagear tradições, criar ironia através do contraste, enriquecer significados através de camadas, ou subverter textos canônicos. Em "Grande Sertão: Veredas", Guimarães Rosa dialoga com a épica clássica; em "Cem Anos de Solidão", García Márquez reinventa mitos bíblicos.', 39, NOW(), NOW()),
('Exemplos', 'Casos famosos incluem: "Ulysses" de Joyce recontando a Odisseia, "O Leitor" de Bernhard Schlink problematizando a cultura letrada, e "Cidade de Deus" de Paulo Lins ressignificando tragédia grega no contexto favelado. Até plágios, quando descobertos, revelam-se formas perversas de intertextualidade.', 39, NOW(), NOW()),

-- Contents for 'Narratologia' (item_id 40)
('Disciplina', 'A narratologia estuda a estrutura e funcionamento das narrativas, independente de seu suporte (literatura, cinema, games). Derivada do formalismo russo e do estruturalismo francês, analisa elementos como: tempo narrativo (ordem, duração, frequência), foco narrativo (quem vê/quem narra), e modos de representação (diálogo, descrição).', 40, NOW(), NOW()),
('Conceitos-chave', 'Termos fundamentais incluem: diegese (universo da história), narrador (extradiegético, intradiegético), focalização (zero, interna, externa), e instâncias narrativas (autor implícito, narrador, leitor implícito). A análise separa história (o que é contado) de discurso (como é contado).', 40, NOW(), NOW()),
('Aplicações', 'A narratologia ajuda a: comparar adaptações de uma obra, entender efeitos de perspectiva (como narrativas não-confiáveis), e criar estruturas inovadoras. Teóricos como Gérard Genette, Mieke Bal e Seymour Chatman desenvolveram ferramentas para desmontar mecanismos narrativos complexos.', 40, NOW(), NOW()),
('Tendências', 'Novas narratologias estudam: narrativas transmídia (que atravessam plataformas), inteligência artificial como narrador, e formas não-humanas de narrar (como algoritmos de redes sociais). A pós-narratologia questiona modelos muito rígidos, incorporando cognição e recepção.', 40, NOW(), NOW()),

-- Contents for 'Sociolinguística' (item_id 41)
('Objeto de Estudo', 'A sociolinguística investiga como fatores sociais (classe, gênero, idade, etnia) influenciam a variação e mudança linguística. Analisa desde padrões fonéticos (como a pronúncia do "r" caipira) até escolhas lexicais (gírias jovens vs. linguagem formal), mostrando que a língua é um sistema heterogêneo e dinâmico.', 41, NOW(), NOW()),
('Métodos', 'Pesquisas usam: entrevistas sociolinguísticas, corpora de fala espontânea, e técnicas estatísticas para correlacionar variáveis linguísticas e sociais. O modelo de Labov sobre estratificação social da linguagem revolucionou o campo, mostrando padrões sistemáticos onde se via apenas "erros".', 41, NOW(), NOW()),
('Aplicações', 'Findings sociolinguísticos informam: políticas de educação bilíngue, planejamento linguístico, marketing (adaptação a públicos), e até investigações forenses (identificação por características de fala). No Brasil, estudos sobre preconceito linguístico ajudaram a valorizar variedades não-padrão.', 41, NOW(), NOW()),
('Tópicos Atuais', 'Tendências incluem: sociolinguística digital (variação em redes sociais), estudos sobre letramento crítico, e abordagens queer da linguagem. Pesquisas brasileiras destacam-se em contato entre línguas (português-indígenas), e análise do português afro-brasileiro.', 41, NOW(), NOW()),

-- Contents for 'Fonética' (item_id 42)
('Ramo da Linguística', 'A fonética estuda os sons da fala humana em seus aspectos articulatórios (como são produzidos), acústicos (propriedades físicas das ondas sonoras), e auditivos (como são percebidos). Diferencia-se da fonologia, que analiza o funcionamento dos sons em sistemas linguísticos específicos.', 42, NOW(), NOW()),
('Técnicas', 'Foneticistas usam: espectrogramas para visualizar formantes, palatografia para mapear contato língua-palato, e softwares como Praat para análise acústica. Estudos articulatórios avançados empregam ressonância magnética e ultrassom para observar órgãos fonadores em ação.', 42, NOW(), NOW()),
('Aplicações', 'Conhecimento fonético é essencial para: ensino de pronúncia de línguas estrangeiras, desenvolvimento de sistemas de reconhecimento de fala, terapia fonoaudiológica, e preservação de línguas ameaçadas (documentação sonora). Cantores e atores também se beneficiam desse entendimento.', 42, NOW(), NOW()),
('Descobertas', 'Pesquisas revelaram: variações dialetais em microtraços articulatórios, padrões universais na aquisição fonética infantil, e adaptações neurológicas ao processar sons não-nativos. Estudos sobre cochichos, cantos e fala em ambientes ruidosos expandem nosso entendimento da produção vocal.', 42, NOW(), NOW()),

-- Contents for 'Nova Ortografia' (item_id 43)
('Mudanças Principais', 'O Acordo Ortográfico de 1990 (efetivo no Brasil desde 2016) buscou unificar 98% da escrita nos países lusófonos. Principais alterações: eliminação do trema (exceto nomes próprios), novas regras para hífen (prefixos + palavras iniciadas por h ou vogal igual), e inclusão de k, w, y no alfabeto. Acento diferencial sumiu em "pára" (verbo) e "pêlo".', 43, NOW(), NOW()),
('Controvérsias', 'O acordo gerou debates sobre: custos da transição (mudança em livros, sistemas), suposta submissão ao português europeu, e perturbação desnecessária. Críticos argumentam que unificação é ilusória (pronúncias continuam diversas) e que mudanças como o fim do trema prejudicam a clareza.', 43, NOW(), NOW()),
('Adaptação', 'Para se adequar: dicionários eletrônicos atualizam automaticamente, corretores ortográficos incorporam as regras, e guias práticos explicam casos dúbios (como "micro-ondas" vs "microondas"). Aprendizado na escola agora enfatiza variações aceitáveis (como "facto"/"fato") sem penalizar usos regionais.', 43, NOW(), NOW()),
('Impacto', 'Estudos mostram que: gerações escolarizadas pós-acordo internalizaram as regras rapidamente, mas adultos mantêm hábitos anteriores. A escrita digital (com autocorreção) acelerou a transição. Português se tornou mais inclusivo de variantes africanas, mas resistências persistem em Portugal.', 43, NOW(), NOW()),

-- Contents for 'Estrangeirismos' (item_id 44)
('Tipos', 'Palavras estrangeiras são incorporadas por: empréstimo puro ("shopping"), tradução ("vale-refeição" do inglês "meal voucher"), ou decalque ("hora de ouro" de "golden hour"). Podem manter pronúncia original ("delivery") ou aportuguesada ("debitar"). Neologismos como "printar" (de "print") mostram a criatividade nesse processo.', 44, NOW(), NOW()),
('Atitudes', 'Reações variam da purista (rejeição de estrangeirismos) à descritivista (aceitação do uso real). No Brasil, termos tecnológicos em inglês são amplamente adotados ("site", "feed"), enquanto Portugal prefere traduções ("sítio", "alimentação"). Setores como direito e medicina mantêm mais latinismos.', 44, NOW(), NOW()),
('Impactos', 'Estrangeirismos podem: enriquecer a língua (novos conceitos), causar ambiguidade ("mouse" animal/dispositivo), ou excluir falantes menos escolarizados. Empresas globais desenvolvem guias de localização para adaptar termos a cada mercado, enquanto governos promovem alternativas (França com "courriel" para "email").', 44, NOW(), NOW()),
('Tendências', 'A internet acelerou a circulação de estrangeirismos, especialmente no vocabulário digital ("hashtag", "fake news"). Novos fenômenos incluem: "emojis" como léxico universal, misturas como "portunhol" em fronteiras, e resistências através de movimentos como "orgulho linguístico" em comunidades minoritárias.', 44, NOW(), NOW()),

-- Contents for 'Photoshop' (item_id 45)
('Ferramentas Essenciais', 'Dominar Photoshop exige compreender: layers (organização não-destrutiva), selection tools (máscaras, canais alpha), adjustment layers (correções reversíveis), e blending modes (como multiplicar ou overlay). Ferramentas como clone stamp, content-aware fill e healing brush são fundamentais para retoques profissionais.', 45, NOW(), NOW()),
('Workflows', 'Profissionais desenvolvem fluxos como: tratamento de fotos (sequência RAW → lens corrections → exposure → color grading → retouch), composição digital (montagens realistas com matching de luz/sombra), ou design gráfico (criação de mockups e materiais promocionais). Atalhos personalizados e actions automatizam tarefas repetitivas.', 45, NOW(), NOW()),
('Técnicas Avançadas', 'Habilidades premium incluem: dodge & burn não-destrutivo, frequency separation para retoques de pele, color grading com LUTs, e manipulações 3D com Photoshop Extended. Integração com Lightroom (para fotógrafos) e Illustrator (para designers) amplia possibilidades criativas.', 45, NOW(), NOW()),
('Aprendizado', 'Recursos para aprender: tutoriais da Adobe, cursos especializados (Phlearn, KelbyOne), desafios como "Daily Photoshop Challenge", e comunidades no Behance/Dribbble. Versões recentes adicionaram AI (Neural Filters) e melhorias em seleção de objetos e preenchimento contextual.', 45, NOW(), NOW()),

-- Contents for 'Pixel Art' (item_id 46)
('Estética', 'Pixel art celebra a restrição como virtude criativa - cada pixel é colocado intencionalmente, evocando jogos retrô e hardware antigo. Estilos variam do minimalista (1-bit) ao detalhado (32-bit era SNES), com técnicas como dithering (mistura óptica de cores) e anti-aliasing manual para suavizar curvas.', 46, NOW(), NOW()),
('Ferramentas', 'Artistas usam: Aseprite (especializado), Photoshop (com configurações específicas), ou até MS Paint. Paletas de cores limitadas (como EGA 16-color ou PICO-8) impõem restrições criativas. Animação frame-by-frame exige planejamento de spritesheets e timing.', 46, NOW(), NOW()),
('Aplicações', 'Além de jogos indies (Celeste, Stardew Valley), pixel art aparece em: NFTs colecionáveis, vinhetas de TV, e até arte generativa. Seu charme nostálgico convive com inovações como shaders dinâmicos e iluminação em tempo real sobre sprites pixelados.', 46, NOW(), NOW()),
('Comunidade', 'Festivais como Pixel Jam e fóruns como Pixel Joint compartilham técnicas e promovem a arte. Desafios comuns incluem: criar dentro de resoluções extremas (16x16), imitar estilos de consoles específicos, ou traduzir fotos reais para pixel art mantendo reconhecibilidade.', 46, NOW(), NOW()),

-- Contents for 'Regra dos Terços' (item_id 47)
('Fundamentos', 'A regra dos terços divide o frame em 9 partes iguais (2 linhas horizontais e 2 verticais). Elementos-chave devem alinhar-se com essas linhas ou seus cruzamentos (pontos de ouro). O horizonte numa paisagem, por exemplo, fica melhor na linha inferior (ênfase no céu) ou superior (ênfase no solo), raramente no centro.', 47, NOW(), NOW()),
('Psicologia', 'A assimetria criada pela regra gera tensão visual mais interessante que composições centradas. Estudos de eye-tracking mostram que olhos naturalmente percorrem os pontos de ouro antes do centro. A regra deriva da proporção áurea, presente em diversas manifestações artísticas históricas.', 47, NOW(), NOW()),
('Variações', 'Além da versão 3x3, composições podem usar: espirais áureas (que conduzem o olhar), triângulos dinâmicos, ou a "regra das odds" (números ímpares de elementos são mais agradáveis). Fotógrafos frequentemente combinam múltiplas guias de composição numa mesma imagem.', 47, NOW(), NOW()),
('Quebrando a Regra', 'Composições centradas funcionam para: retratos formais, simetrias arquitetônicas, ou quando se busca impacto direto. Saber quando seguir ou quebrar a regra diferencia amadores de profissionais - a regra deve servir à mensagem, não limitar a criatividade.', 47, NOW(), NOW()),

-- Contents for 'Longa Exposição' (item_id 48)
('Técnica', 'Fotografia de longa exposição usa tempos de obturação prolongados (de segundos a horas) para capturar a passagem do tempo. Requer: tripé estável, controle manual de exposição (prioridade de abertura ou modo bulb), e muitas vezes filtros ND para reduzir entrada de luz. Resultados típicos incluem: água aveludada, rastros de luz, e cidades sem pessoas.', 48, NOW(), NOW()),
('Cenários', 'Aplicações comuns: cachoeiras e marés (efeito seda), tráfego noturno (rastros de faróis), astrofotografia (startrails), e light painting (desenhar com fontes luminosas). Fotógrafos exploram criativamente a técnica para abstrações ou documentar processos lentos (construções, mudança de estações).', 48, NOW(), NOW()),
('Desafios', 'Problemas frequentes: overexposure mesmo com ISO mínimo e abertura fechada (requer filtros ND fortes), vibration reduction que deve ser desligado, e hot pixels em exposições muito longas. Fotógrafos levam lanternas para ajustes no escuro e apps para calcular exposição com filtros.', 48, NOW(), NOW()),
('Pós-processamento', 'Longas exposições frequentemente exigem: redução de ruído (especialmente em sombras), ajuste de white balance (luz artificial cria dominantes), e às vezes compositing (combinar múltiplas exposições). Técnicas como time stacking (empilhar fotos sequenciais) simulam o efeito sem filtros ND.', 48, NOW(), NOW()),

-- Contents for 'Turismo Sustentável' (item_id 49)
('Princípios', 'O turismo sustentável busca minimizar impactos ambientais, respeitar culturas locais, e gerar benefícios econômicos para comunidades anfitriãs. Diretrizes incluem: preferir acomodações eco-certificadas, reduzir pegada de carbono (transporte terrestre vs aéreo), e apoiar negócios locais em vez de cadeias globais.', 49, NOW(), NOW()),
('Certificações', 'Selo GSTC (Global Sustainable Tourism Council) valida operadores comprometidos com: conservação de recursos, proteção à biodiversidade, e condições justas de trabalho. Programas como Rainforest Alliance e EarthCheck oferecem certificação para hotéis. Viajantes podem consultar plataformas como BookDifferent para opções sustentáveis.', 49, NOW(), NOW()),
('Destinos', 'Exemplos de boas práticas: Costa Rica (30% do território protegido, energia renovável), Butão (turismo de alto valor/baixo volume), e Fernando de Noronha (limite de visitantes, taxa de preservação). Cidades como Barcelona e Amsterdã combatem overtourism com regulamentação e taxação.', 49, NOW(), NOW()),
('Tendências', 'Novos modelos incluem: volunturismo (combina viagem e trabalho social), ecoturismo regenerativo (que melhora áreas degradadas), e slow travel (permanências longas com imersão cultural). A pandemia acelerou demanda por destinos menos massificados e acomodações com espaços abertos.', 49, NOW(), NOW()),

-- Contents for 'Biomas Brasileiros' (item_id 50)
('Diversidade', 'O Brasil abriga 6 biomas continentais: Amazônia (maior floresta tropical), Cerrado (savana mais biodiversa), Mata Atlântica (hotspot ameaçado), Caatinga (exclusivamente brasileira), Pampa (campos sulinos), e Pantanal (maior área úmida). Cada um possui clima, solo, flora e fauna distintivos, além de culturas humanas adaptadas.', 50, NOW(), NOW()),
('Ameaças', 'Principais riscos: Amazônia (desmatamento para agropecuária), Cerrado (expansão da soja), Mata Atlântica (fragmentação urbana), Caatinga (desertificação), Pampa (conversão em silvicultura), e Pantanal (queimadas e hidrovias). Mudanças climáticas exacerbam esses processos, com savanização da Amazônia como cenário preocupante.', 50, NOW(), NOW()),
('Conservação', 'Estratégias de proteção incluem: unidades de conservação (parques, reservas), corredores ecológicos, pagamento por serviços ambientais, e manejo sustentável por comunidades tradicionais. Projetos como ARPA (Amazônia) e Pacto pela Restauração da Mata Atlântica buscam escalar esforços.', 50, NOW(), NOW()),
('Turismo Responsável', 'Cada bioma oferece experiências únicas: observação de onças-pintadas no Pantanal, trilhas na Chapada Diamantina (Caatinga), mergulho em Abrolhos (Mata Atlântica marinha). Operadores sérios seguem códigos de conduta para minimizar impactos e envolver guias locais.', 50, NOW(), NOW()),

-- Contents for 'Comida de Rua' (item_id 51)
('Cultura e História', 'A comida de rua reflete a alma culinária de cada lugar, desde os tacos mexicanos até os banh mi vietnamitas. No Brasil, evoluiu dos tabuleiros coloniais para uma cena vibrante com pastel de feira, acarajé baiano, e gourmetizações como hot dogs artesanais. Esses alimentos contam histórias de migração, adaptação e criatividade popular.', 51, NOW(), NOW()),
('Segurança Alimentar', 'Consumir comida de rua com segurança requer observar: higiene do vendedor (luvas, touca), temperatura dos alimentos (cuidado com maionese exposta), movimento do local (alta rotatividade indica frescor), e água para lavagem de utensílios. Cidades como Singapura implementaram rigorosos programas de capacitação para vendedores.', 51, NOW(), NOW()),
('Tendências', 'A cena contemporânea mistura tradição e inovação: food trucks com cozinha de autor, redes sociais divulgando pontos obscuros, e fusões como esfirras árabes com recheios brasileiros. Eventos como feiras noturnas e festivais de comida de rua tornaram-se programas culturais.', 51, NOW(), NOW()),
('Sustentabilidade', 'Desafios incluem: reduzir plásticos descartáveis (muitos vendedores adotam embalagens comestíveis ou biodegradáveis), aproveitamento integral de alimentos, e inclusão de produtores locais. Projetos como "Comida Invisível" combatem o desperdício na comida de rua.', 51, NOW(), NOW()),

-- Contents for 'Fusion Food' (item_id 52)
('Conceito', 'Fusion food combina técnicas e ingredientes de tradições culinárias distintas, resultando em pratos como sushi brasileiro (com manga e cream cheese) ou ramen mexicano. Diferente da mestiçagem culinária histórica (como a culinária peruano-japonesa), a fusão moderna é intencional e frequentemente gourmet.', 52, NOW(), NOW()),
('Críticas', 'Alguns puristas consideram a fusão como apropriação cultural, especialmente quando chefs privilegiados lucram com tradições marginalizadas. Fusões bem-sucedidas respeitam a essência das cozinhas originais e dão crédito às inspirações, evitando exotização superficial.', 52, NOW(), NOW()),
('Exemplos', 'Casos celebrados incluem: kofta de berinjela com tahine (fusão árabe-mediterrânea), tacos de peixe com kimchi (coreano-mexicano), e moqueca de banana-da-terra (afro-indígena contemporânea). Restaurantes como Nobu popularizaram a fusão japonesa-peruana globalmente.', 52, NOW(), NOW()),
('Tendências', 'Novas fronteiras da fusão exploram: ingredientes amazônicos em técnicas francesas, fermentações ancestrais em pratos modernos, e "hyper-local fusion" que combina vizinhanças específicas (como culinária paulistana misturando Bixiga e Liberdade). A fusão também entra em drinks e sobremesas.', 52, NOW(), NOW()),

-- Contents for 'Esferificação' (item_id 53)
('Técnica', 'A esferificação, popularizada por Ferran Adrià, transforma líquidos em esferas gelatinosas através de reação entre alginato (extraído de algas) e cálcio. Existem dois métodos: básico (esfera com líquido dentro e pele fina) e reverso (pele mais espessa, líquido externo). O resultado são "caviar" ou "ovos" que explodem na boca.', 53, NOW(), NOW()),
('Aplicações', 'Chefs usam a técnica para: azeites em forma de caviar, cóquetis encapsulados, ou molhos que se rompem ao cortar. Versões caseiras simplificadas usam kits com ingredientes pré-dosados. A esferificação permite brincar com expectativas - uma esfera transparente pode revelar sabores surpreendentes.', 53, NOW(), NOW()),
('Desafios', 'Problemas comuns incluem: esferas que colam umas às outras, tempo de reação muito rápido para trabalhar, e sabores alterados pelo alginato. Ajustar pH (com citrato de sódio) e temperatura dos banhos melhora resultados. Esferas devem ser servidas imediatamente - não armazenam bem.', 53, NOW(), NOW()),
('Variantes', 'Técnicas relacionadas incluem: gelificação (com agar ou gellan), espessamento (com xantana), e emulsificação (como aires). A "esferificação invertida" é mais fácil para líquidos com cálcio natural (como leite), enquanto a básica funciona melhor com sucos ácidos.', 53, NOW(), NOW()),

-- Contents for 'Nitrogênio Líquido' (item_id 54)
('Uso Culinário', 'O nitrogênio líquido (-196°C) permite técnicas como: congelamento ultra-rápido (criando texturas cremosas sem cristais de gelo), "fritura" de sorvetes, e efeitos dramáticos de fumaça. Restaurantes como o Alinea usam para criar pratos performáticos, onde componentes são finalizados à mesa.', 54, NOW(), NOW()),
('Segurança', 'Manusear requer: luvas criogênicas, óculos de proteção, e ambientes ventilados (para evitar asfixia por deslocamento de oxigênio). Alimentos tratados devem "descansar" para que o nitrogênio residual evapore - nunca consumir imediatamente após contato. Treinamento adequado previne queimaduras graves.', 54, NOW(), NOW()),
('Aplicações', 'Além de sorvetes, cria: mousses aéreas, "rocas" de chocolate que quebram dramaticamente, e instantâneos como congelar ervas para esfarelar sobre pratos. Barmen usam para rapidamente resfriar copos ou criar coquetis com cascas congeladas que estouram ao beber.', 54, NOW(), NOW()),
('Alternativas', 'Para quem não tem acesso a nitrogênio, técnicas similares (menos extremas) usam: dry ice (gelo seco) para efeitos de fumaça, ou álcool isopropílico com gelo para congelamento rápido. Kits de cozinha molecular caseiros oferecem versões mais seguras de algumas técnicas.', 54, NOW(), NOW()),

-- Contents for 'Fermentação Natural' (item_id 55)
('Processo', 'A fermentação natural de pães utiliza levain (massa mãe) - uma cultura simbiótica de leveduras (como Saccharomyces) e bactérias lácticas desenvolvida ao longo de dias. Diferente do fermento industrial, produz pães com sabor complexo (notas ácidas e frutadas), melhor digestibilidade, e maior shelf life.', 55, NOW(), NOW()),
('Técnicas', 'Manter um starter vivo requer: alimentação regular (farinha e água), temperaturas estáveis, e descartes periódicos. Padeiros ajustam variáveis como hidratação, temperatura de fermentação (bulk vs cold proof), e dobramentos para controlar acidez e estrutura da massa. Fermentações longas (até 24h) desenvolvem sabores profundos.', 55, NOW(), NOW()),
('Benefícios', 'Além de qualidades sensoriais, pães de fermentação natural têm: índice glicêmico mais baixo, maior disponibilidade de nutrientes (fitato reduzido), e diversidade microbiana potencialmente benéfica. Alguns portadores de sensibilidade ao glúten toleram melhor esses pães.', 55, NOW(), NOW()),
('Cultura', 'A arte do sourdough teve revival recente, com comunidades online trocando starters (alguns com décadas) e técnicas. Durante a pandemia, a escassez de fermento biológico levou muitos a experimentarem a fermentação natural caseira, documentando jornadas no Instagram.', 55, NOW(), NOW()),

-- Contents for 'Massas Madre' (item_id 56)
('Criação', 'Uma massa madre (ou levain) inicia-se misturando farinha e água e deixando capturar leveduras ambientais. Nos primeiros dias, bactérias indesejáveis dominam (fase de "falso crescimento"), até leveduras benéficas estabelecerem-se. Sinais de saúde incluem bolhas regulares e aroma agradavelmente ácido (não putrefato).', 56, NOW(), NOW()),
('Manutenção', 'Massas madres ativas requerem: alimentação com farinha integral ou branca (ou mistura), água sem cloro, e descartes para renovar população microbiana. Guardadas na geladeira, podem ser alimentadas semanalmente; em temperatura ambiente, diariamente. Alguns starters especializam-se em farinhas específicas (centeio, espelta).', 56, NOW(), NOW()),
('Problemas', 'Issues comuns incluem: starter "faminto" (líquido por cima, cheiro alcoólico), excesso de acidez (requer alimentações mais frequentes), ou contaminação (cores anormais, mofo). A maioria pode ser recuperada com descartes e alimentações consistentes. Starters podem ser desidratados para armazenamento ou envio.', 56, NOW(), NOW()),
('Variedades', 'Diferentes regiões desenvolveram starters únicos: o levain francês (mais ácido), o biga italiano (mais hidratado), ou o poolish (pre-fermento líquido). Pesquisas com starters históricos (como de cervejarias antigas) buscam resgatar sabores perdidos.', 56, NOW(), NOW()),

-- Contents for 'Mixagem Básica' (item_id 57)
('Fundamentos', 'Mixar é balancear elementos de uma música (vocais, instrumentos) no espaço estéreo e espectral. Começa com: balanceamento de volumes (faders), panning (posicionamento esquerdo-direito), e equalização (EQ) para evitar sobreposição frequencial. O objetivo é clareza - cada elemento deve ser ouvido distintamente.', 57, NOW(), NOW()),
('Técnicas Iniciais', 'Passos básicos incluem: cortar frequências baixas desnecessárias (high-pass filter), criar espaço para vocais com EQ (cortar mids em instrumentos), e usar compressão leve para controlar dinâmica. Reverb e delay são adicionados com moderação para profundidade, sem embolar o mix.', 57, NOW(), NOW()),
('Ferramentas', 'DAWs (Digital Audio Workstations) como Ableton Live, Logic Pro ou Pro Tools oferecem: equalizadores paramétricos, compressores, e visualizadores de espectro. Plugins como iZotope Neutron ajudam iniciantes com sugestões automáticas de balanceamento. Monitores de estúdio (não fones comuns) são essenciais.', 57, NOW(), NOW()),
('Erros Comuns', 'Iniciantes frequentemente: exageram em baixos e altos (mix "sorridente"), sobrecarregam o centro (panning tudo no meio), ou abusam de efeitos. Referenciar mixes profissionais em sistemas variados (carro, celular) ajuda a identificar problemas. Paciência é chave - ouvidos cansados perdem objetividade.', 57, NOW(), NOW()),

-- Contents for 'Masterização' (item_id 58)
('Objetivo', 'Masterização é o polimento final que prepara uma mixagem para distribuição, garantindo consistência entre faixas e adequação a padrões de loudness (como -14 LUFS para streaming). Envolve: equalização sutil, compressão multibanda, limitação de pico, e ajustes estéreo, sem alterar drasticamente o balanceamento do mix.', 58, NOW(), NOW()),
('Processo', 'Engenheiros de masterização usam: equalizadores lineares (como Weiss), compressores vari-mu (tubo), e limitadores precisos (como FabFilter Pro-L 2). Analisadores (LUFS, espectro, fase) guiam decisões. O "master bus" recebe processamento leve, diferente da mixagem onde cada trilha é tratada individualmente.', 58, NOW(), NOW()),
('Formatos', 'Diferentes plataformas exigem masters específicos: vinil requer corte de baixos extremos e mono abaixo de 150Hz, streaming pede headroom (não maximizar a 0dB), e rádio solicita versões com menos compressão. Stem mastering (grupos de instrumentos) oferece mais flexibilidade que mixagem estéreo.', 58, NOW(), NOW()),
('DIY vs Profissional', 'Artistas independentes usam serviços como LANDR ou plugins como iZotope Ozone para auto-masterização, mas um engenheiro experiente traz: ouvidos treinados, ambiente acústico tratado, e equipamento de alta qualidade. Para lançamentos importantes, o investimento geralmente vale a pena.', 58, NOW(), NOW()),

-- Contents for 'Escalas Musicais' (item_id 59)
('Tipos', 'Escalas são sequências de notas que formam a base de melodias e harmonias. Principais tipos: maior (alegre, estável), menor (triste, com variantes natural, harmônica e melódica), pentatônica (5 notas, comum no blues), e modais (dórico, frígio etc., cada um com "personalidade" distinta).', 59, NOW(), NOW()),
('Construção', 'Escalas são definidas por intervalos entre notas: a maior segue T-T-ST-T-T-T-ST (T=tom, ST=semitom). No piano, a escala de Dó maior usa apenas teclas brancas. Transpor para outras tonalidades exige sustenidos ou bemóis para manter a sequência intervalar. O círculo de quintas mostra relações entre tonalidades.', 59, NOW(), NOW()),
('Uso Prático', 'Compositores escolhem escalas para evocar emoções: lídio (sonho), mixolídio (rock/blues), ou escala cromática (tensão). Improvisadores aprendem "formas" de escalas no braço do violão. Produções eletrônicas frequentemente usam escalas sintéticas (como escala hexafônica) para timbres futuristas.', 59, NOW(), NOW()),
('Culturas', 'Diferentes tradições desenvolveram escalas únicas: maqam árabe (quartos de tom), raga indiano (microtonalidades), ou pelog javanês (5 notas assimétricas). A música ocidental contemporânea redescobre essas possibilidades através da world music e do jazz fusion.', 59, NOW(), NOW()),

-- Contents for 'Harmonia Básica' (item_id 60)
('Acordes', 'Harmonia estuda como notas soam juntas. Acordes triádicos (3 notas) são classificados como: maior (fundamental+3ªM+5ªJ), menor (3ªm), aumentado (5ªA) ou diminuto (3ªm+5ªD). Tétrades adicionam a 7ª (como dominante7: 3ªM+5ªJ+7ªm). Progressões como I-V-vi-IV são onipresentes na pop music.', 60, NOW(), NOW()),
('Funções', 'Na tonalidade, acordes têm funções: tônica (repouso, grau I), dominante (tensão, V), e subdominante (ponte, IV). O ciclo V-I (cadência perfeita) cria forte sensação de resolução. Jazz expande com substituições (IIm7 no lugar de IV) e acordes estendidos (9ª, 11ª, 13ª).', 60, NOW(), NOW()),
('Voicing', 'Posicionamento das notas do acorde (voicing) afeta o som: posição feita (notas próximas) soam compactas, abertas (espaçadas) são mais ricas. Inversões (não-fundamental no baixo) suavizam progressões. Pianistas e arranjadores estudam voice leading (movimento suave entre vozes).', 60, NOW(), NOW()),
('Exercícios', 'Para praticar: tocar progressões em todas as 12 tonalidades, analisar harmonias de músicas conhecidas, e experimentar reharmonizações (trocar acordes mantendo a melodia). Apps como iReal Pro oferecem backing tracks para improvisação sobre diferentes progressões.', 60, NOW(), NOW()),

-- Contents for 'Kettlebell' (item_id 61)
('Exercícios Básicos', 'O kettlebell permite movimentos balísticos e de força: swing (base para outros exercícios, trabalfa cadeia posterior), goblet squat (pernas e core), turkish get-up (coordenação total), e press militar (ombros). Técnica adequada previne lesões - iniciantes devem focar em hinge (dobrar quadril, não coluna) no swing.', 61, NOW(), NOW()),
('Benefícios', 'Treinos com kettlebell desenvolvem: força explosiva (devido ao centro de massa deslocado), resistência cardiovascular (circuitos elevam frequência cardíaca), e mobilidade (exercícios como halo melhoram amplitude articular). É eficiente para quem tem pouco tempo ou espaço.', 61, NOW(), NOW()),
('Programação', 'Rotinas populares incluem: EMOM (Every Minute On the Minute), complexos (sequências sem soltar o peso), e protocolos como Simple & Sinister (100 swings + 10 get-ups). Peso inicial varia: homens 16-24kg, mulheres 8-16kg para swings; menos para exercícios overhead.', 61, NOW(), NOW()),
('Segurança', 'Precauções incluem: aquecimento articular (especialmente ombros e quadril), espaço livre para balançar, e atenção à fadiga (técnica degradada causa lesões). Kettlebells devem ser de aço fundido (não plástico com pesos ajustáveis) para dinâmica adequada.', 61, NOW(), NOW()),

-- Contents for 'HIIT' (item_id 62)
('Metodologia', 'HIIT (High-Intensity Interval Training) alterna períodos curtos de esforço máximo (85-100% FCmax) com recuperação ativa ou passiva. Protocolos comuns: Tabata (20s on/10s off), Little-Gibbards (60s/60s), ou personalizados (ex: 30s sprint/90s caminhada). A vantagem é conseguir benefícios cardiovasculares em sessões curtas (15-30min).', 62, NOW(), NOW()),
('Variações', 'Pode ser adaptado para: corrida (esteira ou outdoor), ciclismo (spinning), bodyweight (burpees, mountain climbers), ou equipamentos (remo, battle ropes). CrossFit incorpora princípios HIIT em WODs (Workouts of the Day). Versões low-impact usam elíptico ou natação.', 62, NOW(), NOW()),
('Benefícios', 'Estudos mostram que HIIT: melhora VO2max mais que cardio estável, aumenta EPOC (consumo de oxigênio pós-treino, "afterburn effect"), e preserva massa muscular melhor que endurance tradicional. É eficiente para quem busca perda de gordura com tempo limitado.', 62, NOW(), NOW()),
('Precauções', 'HIIT não é para todos: iniciantes devem progredir de cardio moderado, e pessoas com condições cardíacas precisam de liberação médica. Sinais de excesso incluem fadiga prolongada, desempenho decrescente, ou distúrbios do sono. Recomenda-se 2-3 sessões semanais não consecutivas.', 62, NOW(), NOW()),

-- Contents for 'Pré-Treino' (item_id 63)
('Nutrientes', 'A nutrição pré-treino visa fornecer energia e prevenir catabolismo. Carboidratos de médio índice glicêmico (aveia, batata-doce) 1-2h antes sustentam performance. Proteínas (whey, ovos) ajudam a iniciar síntese proteica. Gorduras boas (abacate, oleaginosas) são melhores em treinos de endurance.', 63, NOW(), NOW()),
('Timing', 'Refeições maiores (500+ kcal) devem ser 2-3h antes, enquanto lanches leves (banana com pasta de amendoim) são ideais 30-60min antes. Treinos em jejum (apenas com água ou café preto) podem queimar mais gordura, mas reduzem intensidade possível - melhor para atividades leves/moderadas.', 63, NOW(), NOW()),
('Suplementos', 'Comuns incluem: cafeína (200-400mg para energia/foco), beta-alanina (reduz fadiga em exercícios anaeróbicos), e citrulina malato (melhora vasodilatação). Evitar excessos que causam dependência ou picos/crashes de energia. Novatos devem testar suplementos em treinos não-críticos.', 63, NOW(), NOW()),
('Hidratação', 'Começar exercícios já hidratado é crucial - urina clara é bom indicador. Bebidas eletrolíticas ajudam se suar muito. Evitar álcool 24h antes (desidrata) e excesso de fibras imediatamente antes (desconforto gastrointestinal).', 63, NOW(), NOW()),

-- Contents for 'Recuperação' (item_id 64)
('Pós-Treino', 'A "janela anabólica" ideal é até 2h após exercício. Consumir proteína (0.4g/kg peso) e carboidratos (3:1 ou 4:1 relação CHO:PRO para endurance) acelera recuperação muscular. Whey protein é absorvido rapidamente; caseína (queijo cottage) fornece aminoácidos sustentados para noite.', 64, NOW(), NOW()),
('Técnicas', 'Além de nutrição: sono de qualidade (hormônio do crescimento repara tecidos), foam rolling (liberação miofascial), e mobilidade ativa (alongamento dinâmico). Banhos de contraste (água quente/fria) reduzem dor muscular de início tardio (DMIT). Atividade leve (caminhada) no dia seguinte melhora circulação.', 64, NOW(), NOW()),
('Suplementos', 'Opções com evidência: creatina (recarrega ATP, reduz fadiga), BCAA (em treinos em jejum), tart cherry juice (anti-inflamatório), e magnésio (para relaxamento muscular). Cuidado com analgésicos - mascaram dor que é sinal importante.', 64, NOW(), NOW()),
('Monitoramento', 'Sinais de recuperação insuficiente incluem: frequência cardíaca elevada ao acordar, desempenho reduzido em treinos consecutivos, e irritabilidade. Apps como Whoop ou Oura Ring ajudam a rastrear readiness (prontidão) com base em variabilidade cardíaca e sono.', 64, NOW(), NOW()),

-- Contents for 'Iluminação Studio' (item_id 65)
('Configurações', 'Iluminação de estúdio básica usa três pontos: key light (principal, 45º do assunto), fill light (preenche sombras, oposto à key), e back light (separa assunto do fundo). Modificadores como softboxes (luz difusa), beauty dishes (transição suave), ou grids (controle de spill) criam efeitos distintos.', 65, NOW(), NOW()),
('Equipamentos', 'Fotógrafos escolhem entre: strobes (flash de estúdio, potência ajustável), continuous lights (LED para vídeo), ou speedlites (flashes portáteis). Acessórios como refletores, flags (bloqueadores), e difusores moldam a luz. Medidores de luz garantem exposição precisa em sistemas manuais.', 65, NOW(), NOW()),
('Técnicas', 'Estilos variam: high-key (luz clara e aberta, poucas sombras), low-key (dramático, sombras profundas), Rembrandt lighting (triângulo de luz na bochecha), ou butterfly (sombra sob o nariz). Fotógrafos de beleza usam setups como clamshell (dois softboxes acima e abaixo) para pele lisa.', 65, NOW(), NOW()),
('Pós-Produção', 'Raw files permitem ajustar white balance e recuperar detalhes em highlights/shadows. Técnicas de dodge & burn refinam a iluminação. Plugins como Imagenomic Portraiture suavizam pele mantendo textura. A iluminação crua deve ser boa - edição só aprimora.', 65, NOW(), NOW()),

-- Contents for 'Retrato Rua' (item_id 66)
('Abordagens', 'Fotografia de retrato de rua varia entre: pedir permissão (conexão mais íntima), candid shots (autenticidade, mas questões éticas), ou mistas (iniciar interação após captura). Fotógrafos como Vivian Maier ou Bruce Gilden representam extremos desse espectro.', 66, NOW(), NOW()),
('Técnicas', 'Dicas práticas incluem: usar lentes 35mm ou 50mm para contexto ambiental, priorizar luz natural (golden hour ou sombras suaves), e buscar fundos não-distratores. Configurar câmera discretamente (pré-focar, modo silencioso) ajuda em cenas espontâneas. Predefinições manuais agilizam ajustes.', 66, NOW(), NOW()),
('Legalidade', 'Leis variam por país: locais públicos geralmente permitem fotos de pessoas (mas não uso comercial sem release). Boa prática incluir: ser transparente sobre intenções, respeitar recusas, e considerar contextos vulneráveis. Fotografar crianças exige especial cuidado.', 66, NOW(), NOW()),
('Edição', 'Retratos de rua frequentemente usam: preto e branco para atemporalidade, cortes apertados que destacam expressões, ou vignetting para direcionar olhar. Preservar imperfeições (rugas, texturas) mantém autenticidade. Série coesas contam histórias sobre comunidades.', 66, NOW(), NOW()),

-- Contents for 'Photoshop Avançado' (item_id 67)
('Seleções Complexas', 'Técnicas avançadas incluem: Select and Mask para cabelos, Color Range para isolamento por tom, e canais alpha para transparências. Seleções baseadas em luminosity masks permitem ajustes precisos em highlights/midtones/shadows. Plugins como TK8 automatizam processos complexos.', 67, NOW(), NOW()),
('Composição', 'Criar montagens realistas exige: matching de perspectiva (Vanishing Point), iluminação consistente (adicionar shadows/shine), e integração de texturas (blending modes como Overlay). Técnicas como displacement mapping fazem elementos seguirem superfícies irregulares.', 67, NOW(), NOW()),
('Retoque', 'Além do básico: frequency separation para pele (textura e cor em layers separados), dodge & burn não-destrutivo (50% gray layer em Overlay), e color grading com LUTs (Lookup Tables). O Content-Aware Fill moderno usa AI para preenchimentos convincentes.', 67, NOW(), NOW()),
('Automação', 'Actions registram sequências para aplicar em batches (redimensionar + sharpen + export). Scripts em JavaScript automatizam tarefas complexas. Integração com Bridge e Lightroom agiliza fluxos de trabalho fotográficos. O Generator exporta assets diretamente para web/mobile.', 67, NOW(), NOW()),

-- Contents for 'Lightroom' (item_id 68)
('Fluxo de Trabalho', 'Lightroom organiza fotos em: Library (seleção, keywords), Develop (ajustes), e módulos para output (print, web). Catálogos (não pastas físicas) mantêm referências a arquivos RAW. Coleções inteligentes filtram automaticamente por critérios como rating ou EXIF data.', 68, NOW(), NOW()),
('Ajustes', 'Ferramentas essenciais incluem: Basic panel (exposure, contrast), Tone Curve, HSL (ajuste seletivo de cores), e calibração de lente. O módulo Develop é não-destrutivo - ajustes são receitas aplicadas na exportação. Presets salvam combinações de ajustes para estilos consistentes.', 68, NOW(), NOW()),
('Gestão', 'Boas práticas: renomear arquivos na importação (data_nome), usar keywords e ratings, e estruturar em pastas por data/evento. Backup do catálogo é crucial. Smart Previews permitem editar sem HD externo conectado. Integração com Photoshop (Edit In) preserva não-destrutividade.', 68, NOW(), NOW()),
('Mobile', 'Lightroom CC sincroniza entre dispositivos via cloud. Versão mobile oferece: RAW editing, presets sincronizados, e captura em DNG. Fotógrafos usam para edição em campo (tablet + stylus) ou backup imediato via smartphone. Assinatura Creative Cloud é necessária para recursos completos.', 68, NOW(), NOW()),

-- Contents for 'Meditação Guiada' (item_id 69)
('Técnicas', 'Meditação guiada utiliza instruções verbais para focar a mente: atenção na respiração, varredura corporal (body scan), ou visualizações (paisagens seguras). Diferente de práticas silenciosas, é acessível para iniciantes - apps como Headspace ou Calm oferecem centenas de sessões temáticas.', 69, NOW(), NOW()),
('Benefícios', 'Estudos mostram redução em: estresse (diminuição cortisol), ansiedade (modulação amígdala), e dor crônica (mudança percepção). Melhora foco (aumento matéria cinzenta pré-frontal) e regulação emocional. Sessões de 10-20min já produzem efeitos mensuráveis.', 69, NOW(), NOW()),
('Adaptações', 'Versões para necessidades específicas incluem: meditação para sono (indução theta waves), pré-competitiva (visualização de desempenho), ou dor (mindfulness-based pain management). Terapias como MBSR (Redução de Estresse Baseada em Mindfulness) estruturam programas de 8 semanas.', 69, NOW(), NOW()),
('Desafios', 'Iniciantes enfrentam: expectativas irreais ("esvaziar a mente"), frustração com pensamentos intrusivos (que são normais), e dificuldade em estabelecer rotina. Começar com sessões curtas (3-5min), usar âncoras físicas (sensação dos pés no chão), e não buscar "performance" ajudam.', 69, NOW(), NOW()),

-- Contents for 'Respiração' (item_id 70)
('Padrões', 'Técnicas respiratórias produzem efeitos distintos: diafragmática (calmante, ativa sistema parassimpático), kapalabhati (energizante, rápida expiração), ou box breathing (4s inalar, 4s segurar, 4s exalar, 4s pausa) para foco. O simples "5-5-5" (inalar/segurar/exalar por 5s) reduz ansiedade aguda.', 70, NOW(), NOW()),
('Mecanismos', 'Respiração controlada influencia: pH sanguíneo (via retenção de CO2), variabilidade cardíaca (sincronização coração-pulmões), e atividade vagal (tono do nervo vago). Técnicas como a Coerência Cardíaca (6 respirações/min) otimizam esses efeitos fisiológicos.', 70, NOW(), NOW()),
('Aplicações', 'Práticas específicas ajudam em: desempenho esportivo (ritmo para nado ou corrida), manejo da raiva (respiração 4-7-8), ou preparação para falar em público (respiração abdominal). Cantores e atores usam exercícios para expandir capacidade pulmonar.', 70, NOW(), NOW()),
('Integração', 'A respiração consciente pode ser praticada em micro-momentos: antes de responder emails, em filas, ou ao acordar. Dispositivos como Spire ou Apple Watch dão feedback em tempo real. Apps como Breathwrk oferecem treinos personalizados por objetivo.', 70, NOW(), NOW()),

-- Contents for 'Posturas Básicas' (item_id 71)
('Fundamentos', 'Asanas (posturas) de yoga para iniciantes incluem: mountain (Tadasana, alinhamento postural), downward dog (Adho Mukha Svanasana, alongamento cadeia posterior), warrior I e II (Virabhadrasana, fortalecimento pernas), e child''s pose (Balasana, repouso). A ênfase está em alinhamento, não profundidade.', 71, NOW(), NOW()),
('Benefícios', 'Prática regular melhora: flexibilidade (alongamento fascial), força isométrica (especialmente core), equilíbrio (propriocepção), e consciência corporal. Posturas invertidas leves (como legs-up-the-wall) auxiliam drenagem linfática e relaxamento.', 71, NOW(), NOW()),
('Sequências', 'Vinyasas básicas conectam posturas com respiração: sun salutation (Surya Namaskar) é a sequência clássica para aquecer. Aulas para iniciantes focam em repetição para construir memória muscular, com modificações (blocos, cintos) para diferentes corpos.', 71, NOW(), NOW()),
('Precauções', 'Contraindicações incluem: hipertensão (evitar inversões), problemas lombares (modificar flexões à frente), ou gravidez (adaptar posturas compressivas). O mantra "sem dor, sem ganho" não se aplica - desconforto leve é normal, dor aguda é sinal de parar.', 71, NOW(), NOW()),

-- Contents for 'Yoga para Dor' (item_id 72)
('Abordagens', 'Yoga terapêutico para dor crônica combina: posturas suaves (restorative yoga), respiração consciente (pranayama), e meditação. Sequências personalizadas aliviam lombalgia (posturas como cat-cow), dor no pescoço (alongamentos cervicais), ou fibromialgia (yin yoga passivo).', 72, NOW(), NOW()),
('Mecanismos', 'Estudos sugerem que yoga reduz dor através de: aumento de GABA (neurotransmissor inibitório), modulação da percepção dolorosa (córtex insular), e melhora na propriocepção (evitando movimentos prejudiciais). A atenção plena rompe o ciclo medo-tensão-dor.', 72, NOW(), NOW()),
('Protocolos', 'Programas como Yoga for Back Pain (Dr. Loren Fishman) prescrevem: posturas específicas para hérnias discais, osteoporose ou artrite. Ajustes com props (almofadas, cadeiras) tornam a prática acessível. Sessões curtas (15-20min) diárias superem aulas longas ocasionais.', 72, NOW(), NOW()),
('Evidências', 'Revisões sistemáticas mostram eficácia para: dor lombar (equivalente a fisioterapia), osteoartrite (melhora mobilidade), e enxaquecas (redução frequência). O Yoga Alliance mantém listas de professores certificados em yoga terapêutico.', 72, NOW(), NOW()),

-- Contents for 'MVP' (item_id 73)
('Conceito', 'Minimum Viable Product (MVP) é a versão mais simples de um produto que valida hipóteses centrais com o mínimo de esforço. Exemplos: Dropbox começou com vídeo demonstrando a funcionalidade, Zappos com site básico fotografando sapatos de lojas físicas. O foco está em aprender, não em perfeição.', 73, NOW(), NOW()),
('Construção', 'Para definir um MVP: identificar hipótese de valor principal (ex: "usuários pagariam por entrega rápida de comida saudável"), selecionar métricas de validação (taxa de conversão, retenção), e construir apenas features essenciais para testá-la. Landing pages, protótipos no Figma, ou concierge MVP (serviço manual por trás de fachada automatizada) são alternativas rápidas.', 73, NOW(), NOW()),
('Armadilhas', 'Erros comuns incluem: adicionar "só mais uma feature" antes de lançar, confundir MVP com produto low-quality, ou testar com público errado (early adopters vs mercado massivo). Um bom MVP deve ser descartável - muitas startups falham ao tentar escalar código escrito rapidamente para validação.', 73, NOW(), NOW()),
('Evolução', 'Após validação, o produto evolui através de feedback loops: medir comportamento real (não apenas pesquisas), priorizar melhorias (framework ICE: Impact, Confidence, Ease), e iterar rapidamente. O MVP do Facebook era diretório de faculdades; do Airbnb, aluguel de colchões em conferências.', 73, NOW(), NOW()),

-- Contents for 'Pivotar' (item_id 74)
('Definição', 'Pivotar é mudar fundamentalmente o modelo de negócios após evidências de que o caminho atual não é sustentável. Pode envolver: novo público-alvo (Slack começou como ferramenta interna para game developers), proposta de valor (Instagram pivotou de check-ins para fotos), ou canal de distribuição (Nintendo passou de cartas para videogames).', 74, NOW(), NOW()),
('Sinais', 'Indicadores para pivotar incluem: métricas estagnadas apesar de otimizações, feedback consistente sobre um diferencial não-planejado, ou mudanças no mercado (regulatórias, tecnológicas). Startups que falharam em pivotar (como Blockbuster rejeitando streaming) tornam-se estudos de caso.', 74, NOW(), NOW()),
('Tipos', 'Classificações comuns: zoom-in (uma feature torna-se o produto principal), zoom-out (produto atual vira feature de algo maior), ou mudança de arquitetura (YouTube começou como dating site com vídeos). Pivots devem preservar aprendizados e ativos anteriores, não ser reinícios totais.', 74, NOW(), NOW()),
('Execução', 'Pivotar com sucesso requer: comunicação clara à equipe/investidores, testes rápidos da nova direção (MVP do pivot), e corte limpo com operações não-alinhadas. O livro "The Lean Startup" de Eric Ries detalhe estratégias para pivotar com base em métricas, não apenas intuição.', 74, NOW(), NOW()),

-- Contents for 'Storytelling' (item_id 75)
('Estrutura', 'Pitchs eficazes contam histórias com: herói (cliente com problema), guia (sua empresa), plano (solução), chamado à ação (investimento/parceria), e visão de sucesso (futuro possível). O framework "StoryBrand" de Donald Miller ajuda a simplificar mensagens nessa estrutura.', 75, NOW(), NOW()),
('Técnicas', 'Táticas poderosas incluem: começar com dados surpreendentes ("A cada 8 segundos, um negócio fecha por..."), usar analogias ("Uber para pet-sitters"), e criar suspense ("Há uma solução que 90% das empresas ignoram"). O storytelling visual (uma imagem por slide) supera textos densos.', 75, NOW(), NOW()),
('Adaptação', 'Diferentes audiências exigem ênfases distintas: investidores querem tração e TAM (mercado total endereçável), clientes querem benefícios concretos, e talentos querem propósito. Versões de 1 minuto (elevator pitch), 5min e 15min devem estar preparadas.', 75, NOW(), NOW()),
('Erros', 'Armadilhas comuns: jargão excessivo, muita informação sobre "como" em vez de "por que", e não antecipar objeções ("Você deve pensar que..."). Gravar em vídeo e analisar postura, tom de voz e ritmo é tão importante quanto o conteúdo verbal.', 75, NOW(), NOW()),

-- Contents for 'Slide Ideal' (item_id 76)
('Design', 'Slides eficazes seguem: 1 ideia por slide, contraste alto (texto escuro em fundo claro), mínimo 30pt font size, e elementos visuais que complementam (não repetem) a fala. Templates como Guy Kawasaki 10/20/30 (10 slides, 20min, 30pt) ou Pitch Deck do Sequoia Capital oferecem estruturas testadas.', 76, NOW(), NOW()),
('Sequência', 'Ordem clássica: problema (dor aguda), solução (seu produto), mercado (TAM/SAM), tração (métricas), tecnologia (diferencial), equipe, competição (posicionamento único), modelo de negócio, projeções, e uso dos fundos. O slide de competição deve mostrar vantagem clara em 2-3 eixos.', 76, NOW(), NOW()),
('Visual', 'Elementos gráficos poderosos incluem: gráficos de adoção (hockey stick), antes/depois da solução, fluxos de usuário simplificados, e fotos reais de clientes (não stock). Ferramentas como Canva, Beautiful.ai ou Pitch.com oferecem templates profissionais para não-designers.', 76, NOW(), NOW()),
('Alternativas', 'Para contextos informais: demos ao vivo (mostrar, não contar), protótipos interativos (Figma, InVision), ou até abandonar slides (conversa com whiteboard). O princípio é adaptar ao público - VCs esperam certa estrutura, enquanto clientes B2B podem preferir casos de uso específicos.', 76, NOW(), NOW()),

-- Contents for 'Vasos Inteligentes' (item_id 77)
('Tecnologia', 'Vasos inteligentes integram: sensores de umidade/PH/luz, reservatórios de água automáticos, e conectividade Wi-Fi para alertas. Modelos como Parrot Pot ou Xiaomi Flower Care usam baterias de longa duração e apps com recomendações específicas para cada espécie vegetal.', 77, NOW(), NOW()),
('Benefícios', 'Para usuários urbanos: reduz falhas na rega (principal causa de morte de plantas), indica momento ideal para adubar, e ensina sobre necessidades de cada planta. Jardins internos com vasos inteligentes podem ter taxa de sucesso 80% maior que métodos tradicionais.', 77, NOW(), NOW()),
('Limitações', 'Desafios incluem: custo alto por vaso (US$50-200), necessidade de recargas periódicas (água, nutrientes), e incompatibilidade com algumas espécies (como cactos que preferem secagem completa). Sistemas não substituem totalmente a observação humana para pragas ou doenças.', 77, NOW(), NOW()),
('Futuro', 'Próximas gerações prometem: integração com assistentes de voz ("Alexa, regar a samambaia"), reconhecimento de plantas por câmera para diagnósticos, e automação completa em jardins modulares. Startups exploram hidroponia doméstica conectada.', 77, NOW(), NOW()),

-- Contents for 'Compostagem' (item_id 78)
('Métodos', 'Compostar em pequenos espaços pode ser feito: vermicompostagem (minhocas processam resíduos em caixas empilháveis), composteiras elétricas (como Lomi, que acelera o processo), ou bokashi (fermentação anaeróbica em baldes). Apartamentos podem compostar até 70% de seus resíduos orgânicos.', 78, NOW(), NOW()),
('Benefícios', 'Além de reduzir lixo: produz adubo rico para plantas caseiras, evita emissões de metano (de aterros), e educa sobre ciclos naturais. Famílias médias geram ~150kg de resíduos compostáveis anualmente - transformados em 30-40kg de composto.', 78, NOW(), NOW()),
('Desafios', 'Barreiras comuns: odor (controlado com balanceamento de materiais secos/úmidos), insetos (usar tela fina), e aprendizado do que pode/não pode compostar (evitar carnes, laticínios). Inverno reduz atividade microbiana, alongando o processo.', 78, NOW(), NOW()),
('Comunidade', 'Alternativas coletivas incluem: pontos de entrega de orgânicos (transformados em compostos comunitários), apps como ShareWaste que conectam doadores a composteiras próximas, ou programas municipais de coleta seletiva de orgânicos.', 78, NOW(), NOW()),

-- Contents for 'Jardim Vertical' (item_id 79)
('Tipos', 'Jardins verticais variam entre: painéis modulares (feltro ou plástico reciclado), estruturas treliçadas com vasos, ou paredes vivas (sistemas hidropônicos integrados). Soluções DIY usam paletes, garrafas PET ou canos PVC. Escolha depende de espaço, orçamento e plantas desejadas (suculentas vs folhagens).', 79, NOW(), NOW()),
('Plantas Ideais', 'Para iniciantes: samambaias (como Nephrolepis), herbáceas (peperômias, jiboia), ou suculentas resistentes (Sedum). Varandas ensolaradas permitem ervas (manjericão, alecrim). Sistemas automatizados expandem opções para morangos ou pequenos vegetais.', 79, NOW(), NOW()),
('Manutenção', 'Cuidados básicos incluem: irrigação por gotejamento (manual ou automatizada), poda regular para evitar sobrecarga, e fertilização quinzenal (soluções líquidas). Jardins hidropônicos requerem monitoramento de pH e nutrientes. Telas à prova dágua protegem paredes.', 79, NOW(), NOW()),
('Vantagens', 'Além da beleza: melhora qualidade do ar (filtragem de VOCS), reduz temperatura interna (evapotranspiração), e amplia espaços pequenos. Escritórios usam para bem-estar ocupacional - plantas aumentam produtividade em 15% segundo estudos.', 79, NOW(), NOW()),

-- Contents for 'Plantas Nativas' (item_id 80)
('Importância', 'Plantas nativas estão adaptadas ao clima e solo locais, requerendo menos água, pesticidas e fertilizantes que espécies exóticas. Elas sustentam polinizadores e fauna regional - um jardim com 70% de nativas tem 10x mais diversidade de vida selvagem que um gramado tradicional.', 80, NOW(), NOW()),
('Seleção', 'No Brasil: árvores como ipê ou jabuticabeira, arbustos como quaresmeira ou pitanga, e herbáceas como trapoeraba ou clúsia. Projetos como "Jardim de Mel" da USP catalogam espécies atrativas para abelhas nativas. Viveiros especializados garantem procedência ética (não extrativismo).', 80, NOW(), NOW()),
('Desafios', 'Barreiras incluem: menor disponibilidade em garden centers convencionais, desconhecimento sobre cuidados específicos, e competição com plantas invasoras (como braquiária). Iniciativas como "Semente Livre" distribuem mudas de nativas ameaçadas.', 80, NOW(), NOW()),
('Tendências', 'Movimentos como "Jardins de Apoio" conectam quintais com corredores verdes para fauna. Arquitetura paisagística incorpora biomas locais em projetos comerciais. Legislações municipais começam a exigir porcentagem de nativas em novos loteamentos.', 80, NOW(), NOW()),

-- Contents for 'Chás Curativos' (item_id 81)
('Ervas Tradicionais', 'Plantas brasileiras com propriedades medicinais: boldo (digestivo), guaco (expectorante), capim-santo (calmante), e carqueja (hepática). Preparo adequado (infusão vs decocção) preserva princípios ativos - geralmente 1 colher de folhas secas por xícara de água, 5-10min de repouso.', 81, NOW(), NOW()),
('Evidências', 'Estudos validam: camomila (ansiolítica leve), hortelã-pimenta (alívio de IBS), e gengibre (anti-náusea). Chá verde (ECGC) tem efeitos neuroprotetores. Atenção: interações medicamentosas existem (erva-de-são-joão reduz efeito de anticoncepcionais). Fitoterapia deve ser orientada.', 81, NOW(), NOW()),
('Cultivo', 'Ervas medicinais prosperam em: vasos com boa drenagem (argila expandida no fundo), sol pleno (4-6h/dia), e colheita matinal (óleos essenciais mais concentrados). Secagem em feixes pendurados em local arejado preserva propriedades. Evitar pesticidas químicos.', 81, NOW(), NOW()),
('Precauções', 'Gestantes devem evitar: poejo, arruda e sene. Chás diuréticos (cavalinha) podem desequilibrar eletrólitos. "Naturais" não significa inócuos - doses excessivas de confrei (hepatotóxico) ou chapéu-de-napoleão (cardiotóxico) são perigosas. Consultar profissional qualificado.', 81, NOW(), NOW()),

-- Contents for 'Ervas Aromáticas' (item_id 82)
('Culinária', 'Principais ervas e usos: manjericão (molho pesto, tomate), alecrim (carnes assadas, pães), tomilho (caldos, legumes), e salsinha (finalização). Combinações clássicas como "bouquet garni" (louro, tomilho, salsinha) aromatizam ensopados. Folhas frescas geralmente adicionadas no final para preservar sabor.', 82, NOW(), NOW()),
('Cultivo', 'Dicas para vasos: terra bem drenada (misturar areia), podas frequentes para estimular ramificação, e colheita regular (evitar floração, que amarga folhas). Janelas ensolaradas (4h sol/dia) sustentam a maioria. Hortelã é invasiva - plantar sozinha ou com barreira física.', 82, NOW(), NOW()),
('Preservação', 'Métodos caseiros: congelar em azeite (forminhas de gelo), secar em microondas (folhas entre papéis, 30s), ou fazer "óleos aromáticos" (ervas em azeite por 2 semanas). Sal de ervas (mistura seca com sal grosso) é tempero versátil.', 82, NOW(), NOW()),
('Variedades', 'Além das tradicionais: experimentar estévia (adoçante natural), stevia (adocicante), ou microgreens (ervas colhidas jovens, com nutrição concentrada). Feiras de mudas oferecem variedades como manjericão-limão ou tomilho-laranja para explorar sabores.', 82, NOW(), NOW());











